INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('ramanuja-sc:source:2.52','Rāmānuja','gita.2.52','sa','commentary','।।2.52।।उक्तप्रकारेण कर्मणि वर्तमानस्य तया वृत्त्या निर्धूतकल्मषस्य ते बुद्धिः यदा मोहकलिलम् अत्यल्पफलसङ्गहेतुभूतं मोहरूपं कलुषं व्यतितरिष्यति। तदा अस्मत्त इतः पूर्वं त्याज्यतया श्रुतस्य फलादेः इतः पश्चात् श्रोतव्यस्य च कृते स्वयम् एव निर्वेदं गन्तासि गमिष्यसि।योगे त्विमां श्रृणु इत्यादिना उक्तस्य आत्मयाथात्म्यज्ञानपूर्वकस्य बुद्धिविशेषसंस्कृतकर्मानुष्ठानस्य लक्षणभूतं योगाख्यं फलम् आह'),
('ramanuja-sc:source:2.53','Rāmānuja','gita.2.53','sa','commentary','।।2.53।। श्रुतिः श्रवणम् अस्मत्तः श्रवणेन वि शेषतः प्रतिपन्ना सकलेतरविसजातीयनित्यनिरतिशयसूक्ष्मतत्त्वविषया स्वयम् अचला एकरूपा बुद्धिः असङ्गकर्मानुष्ठानेन विमलीकृते मनसि यदा निश्चला स्थास्यति तदा योगम् आत्मावलोकनम् अवाप्स्यसि। एतद् उक्तं भवति शास्त्रजन्यात्मज्ञानपूर्वककर्मयोगः स्थितप्रज्ञताख्यज्ञाननिष्ठाम् आपादयति ज्ञाननिष्ठारूपा स्थितप्रज्ञता तु योगाख्यम् आत्मावलोकनं साधयति इति।एवम् उक्तः पार्थो निःसङ्गकर्मानुष्ठानरूपकर्मयोगसाध्यस्थितप्रज्ञतया योगसाधनभूतायाः स्वरूपं स्थितप्रज्ञस्यानुष्ठानप्रकारं च पृच्छति'),
('ramanuja-sc:source:2.54','Rāmānuja','gita.2.54','sa','commentary','।।2.54।।अर्जुन उवाच समाधिस्थस्य स्थितप्रज्ञस्य का भाषा को वाचकः शब्दः तस्य स्वरूपं कीदृशम् इत्यर्थः। स्थितप्रज्ञः किं च भाषणादिकं करोति।वृत्तिविशेषकथनेन स्वरूपम् अपि उक्तं भवति इति वृत्तिविशेष उच्यते'),
('ramanuja-sc:source:2.55','Rāmānuja','gita.2.55','sa','commentary','।।2.55।।श्री भगवानुवाच आत्मनि एव आत्मना मनसा आत्मैकावलम्बनेन तुष्टः तेन तोषेण तद्व्यतिरिक्तान् सर्वान् मनोगतान् कामान् यदा प्रकर्षेण जहाति तदा अयं स्थितप्रज्ञ इति उच्यते। ज्ञाननिष्ठाकाष्ठा इयम्।अनन्तरं ज्ञाननिष्ठस्य ततः अर्वाचीना अदूरविप्रकृष्टावस्था उच्यते'),
('ramanuja-sc:source:2.56','Rāmānuja','gita.2.56','sa','commentary','।।2.56।।प्रियविश्लेषादि दुःखनिमित्तेषु उपस्थितेषु अनुद्विग्नमनाः न दुःखी भवति सुखेषु विगतस्पृहः प्रियेषु सन्निहितेषु अपि निःस्पृहः वीतरागभयक्रोधः अनागतेषु स्पृहा रागस्तद्रवितः प्रियविश्लेषाप्रियागमनहेतुदर्शननिमित्तिं दुःखं भयम् तद्रहितः प्रियविश्लेषाप्रियागमनहेतुभूतचेतनान्तरगतो दुःखहेतुः स्वमनोविकारः क्रोधः तद्रहितः एवंभूतो मुनिः आत्ममननशीलः स्थितधीः इति उच्यते।ततः अर्वाचीनदशा प्रोच्यते'),
('ramanuja-sc:source:2.57','Rāmānuja','gita.2.57','sa','commentary','।।2.57।। यः सर्वत्र प्रियेषु अनभिस्नेहः उदासीनः प्रियसंश्लेषविश्लेषरूपं शुभाशुभं प्राप्य अभिनन्दनद्वेषरहितः सोऽपि स्थितप्रज्ञः।ततः अर्वाचीनदशा प्रोच्यते'),
('ramanuja-sc:source:2.58','Rāmānuja','gita.2.58','sa','commentary','।।2.58।। यदा इन्द्रियाणि इन्द्रियार्थान् स्प्रष्टुम् उद्युक्तानि तदा एव कूर्मः अङ्गानि इव इन्द्रियार्थेभ्यः सर्वशः प्रतिसंहृत्य मन आत्मनि एव स्थापयति सोऽपि स्थितप्रज्ञः।एवं चतुर्विधा ज्ञाननिष्ठा पूर्वपूर्वोत्तरोत्तरनिष्पाद्या इति प्रतिपादितम्। इदानीं ज्ञाननिष्ठाया दुष्प्रापतां तत्प्राप्त्युपायं च आह'),
('ramanuja-sc:source:2.59','Rāmānuja','gita.2.59','sa','commentary','।।2.59।।इन्द्रियाणाम् आहारो विषयाः निराहारस्य विषयेभ्यः प्रत्याहृतेन्द्रियस्य देहिनो विषयाः विनिवर्तमाना रसवर्जं विनिवर्तन्ते। रसो रागः विषयरागो न निवर्तते इत्यर्थः। रागः अपि आत्मस्वरूपं विषयेभ्यः परं सुखतरं दृष्ट्वा विनिवर्तते।'),
('ramanuja-sc:source:2.60','Rāmānuja','gita.2.60','sa','commentary','।।2.60।।आत्मदर्शनेन विना विषयरागो न निवर्तते अनिवृत्ते विषयरागे विपश्चितो यतमानस्य अपि पुरुषस्य इन्द्रियाणि प्रमाथीनि बलवन्ति मनः प्रसह्य हरन्ति। एवम् इन्द्रियजय आत्मदर्शनाधीन आत्मदर्शनम् इन्द्रियजयाधीनम् इति ज्ञाननिष्ठा दुष्प्राप्या।'),
('ramanuja-sc:source:2.61','Rāmānuja','gita.2.61','sa','commentary','।।2.61।।सर्वस्य दोषस्य परिजिहीर्षया विषयानुरागयुक्ततया दुर्जयानि इन्द्रियाणि संयम्य चेतसः शुभाश्रय भूते मयि मनः अवस्थाप्य समाहितः आसीत। मनसि मद्विषये सति निर्दग्धाशेषकल्मषतया निर्मलीकृतं विषयानुरागरहितं मन इन्द्रियाणि स्ववशानि करोति। ततो वश्येन्द्रियं मन आत्मदर्शनाय प्रभवति। उक्तं च यथाग्निरुद्धतशिखः कक्षं दहति सानिलः। तथा चित्तस्थितो विष्णुर्योगिनां सर्वकिल्बिषम्।। (वि0 पु0 6।7।74) इति। तदाह वशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता इति।एवं मयि अनिवेश्य मनः स्वयत्नगौरवेण इन्द्रियजये प्रवृत्तो विनष्टो भवति इत्याह'),
('ramanuja-sc:source:2.62','Rāmānuja','gita.2.62','sa','commentary','।।2.62।।अनिरस्तविषयानुरागस्य हि मयि अनिवेशतिमनस इन्द्रियाणि संयम्य अवस्थितस्य अपि अनादिपापवासनया विषयध्यानम् अवर्जनीयं स्यात्। ध्यायतो विषयान् पुंसः पुनरपि सङ्गः अतिप्रवृद्धो जायते। सङ्गात् संजायते कामः। कामो नाम सङ्गस्य विपाकदशा। पुरुषो यां दशाम् आपन्नो विषयान् अभुक्त्वा स्थातुं न शक्नोति स कामः। कामात् क्रोधः अभिजायते। कामे वर्तमाने विषये च असन्निहिते सन्निहितान् पुरुषान् प्रति एभिः अस्मदिष्टं विहतम् इति क्रोधो भवति।'),
('ramanuja-sc:source:2.63','Rāmānuja','gita.2.63','sa','commentary','।।2.63।। क्रोधाद् भवति संमोहः। संमोहः कृत्याकृत्यविवेकशून्यता तया सर्वं करोति। ततश्च प्रारब्धे इन्द्रियजयादिके प्रयत्ने स्मृतिभ्रंशो भवति। स्मृतिभ्रंशाद् बुद्धिनाशः आत्मज्ञाने यो व्यवसायः कृतः तस्य नाशः स्यात्। बुद्धिनाशाद् पुनरपि संसारे निमग्नो नष्टो भवति।'),
('ramanuja-sc:source:2.64','Rāmānuja','gita.2.64','sa','commentary','।।2.64।।उक्तेन प्रकारेण मयि सर्वेश्वरे चेतसः शुभाश्रयभूते न्यस्तमना निर्दग्धाशेषकल्मषतया रागद्वेषवियुक्तैः आत्मवश्यैः इन्द्रियैः विषयान् चरन् विषयान् तिरस्कृत्य वर्तमानो विधेयात्मा विधेयमनाः प्रसादम् अधिगच्छति। निर्मलान्तःकरणो भवति इत्यर्थः।'),
('ramanuja-sc:source:2.65','Rāmānuja','gita.2.65','sa','commentary','।।2.65।।अस्य पुरुषस्य मनसः प्रसादे सति प्रकृतिसंसर्गप्रयुक्तसर्वदुःखानां हानिः उपजायते। प्रसन्नचेतसः आत्मावलोकनविरोधिदोषरहितमनसः तदानीम् एव हि विविक्तात्मविषया बुद्धिः मयि पर्यवतिष्ठते अतो मनःप्रसादे सर्वदुःखानां हानिः भवति एव।'),
('ramanuja-sc:source:2.66','Rāmānuja','gita.2.66','sa','commentary','।।2.66।।मयि संन्यस्तमनोरहितस्य खयत्नेन इन्द्रियदमने प्रवृत्तस्य कदाचिद् अपि विविक्तात्मविषया बुद्धिः न सेत्स्यति। अत एव तस्य तद्भावना च न संभवति। विविक्तात्मानम् अभावयतो विषयस्पृहा शान्तिः न भवति। अशान्तस्य विषयस्पृहायुक्तस्य कुतो नित्यनिरतिशयसुखप्राप्तिः।पुनरपि उक्तेन प्रकारेण इन्द्रियनियमनम् अकुर्वतः अनर्थम् आह'),
('ramanuja-sc:source:2.67','Rāmānuja','gita.2.67','sa','commentary','।।2.67।। इन्द्रियाणां विषयेषु चरतां विषयेषु वर्तमानानां वर्तनम् अनु यन्मनः अनु विधीयते पुरुषेण अनुवर्त्यते तत् मनः अस्य विविक्तात्मप्रवणां प्रज्ञां हरति विषेयप्रवणतां करोति इत्यर्थः। यथा अम्भसि नीयमानां नावं प्रतिकूलो वायुः प्रसह्य हरति।'),
('ramanuja-sc:source:2.68','Rāmānuja','gita.2.68','sa','commentary','।।2.68।। तस्माद् उक्तेन प्रकारेण शुभाश्रये मयि निविष्टमनसो यस्य इन्द्रियाणि इन्द्रियार्थेभ्यः सर्वशो निगृहीतानि तस्य एव आत्मनि प्रज्ञा प्रतिष्ठिता भवति।एवं नियतेन्द्रियस्य प्रसन्नमनसः सिद्धिम् आह'),
('ramanuja-sc:source:2.69','Rāmānuja','gita.2.69','sa','commentary','।।2.69।। या आत्मविषया बुद्धिः सर्वभूतानां निशा निशा इव अप्रकाशिका। तस्याम् आत्मविषयायां बुद्धौ इन्द्रिय संयमी प्रसन्नमना जागर्ति आत्मानम् अवलोकयन् आस्ते इत्यर्थः। यस्यां शब्दादिविषयायां बुद्धौ सर्वाणि भूतानि जाग्रति प्रबुद्धानि भवन्ति सा शब्दादिविषया बुद्धिः आत्मानं पश्यतो मुनेः निशा इव अप्रकाशिका भवति।'),
('ramanuja-sc:source:2.70','Rāmānuja','gita.2.70','sa','commentary','।।2.70।।यथा आत्मना एव आपूर्यमाणम् एकरूपं समुद्रं नादेया आपः प्रविशन्ति आसाम् अपां प्रवेशे अपि अप्रवेशे वा समुद्रो न कञ्चन विशेषम् आपद्यते। एवं सर्वे कामाः शब्दादिविषया यं संयमिनं प्रविशन्ति इन्द्रियगोचरतां यान्ति स शान्तिम् आप्नोति। शब्दादिषु इन्द्रियगोचरताम् आपन्नेषु अनापन्नेषु च स्वात्मावलोकनतृप्त्या एव यो न विकारम् आप्नोति स एव शान्तिम् आप्नोति इत्यर्थः न कामकामी यः शब्दादिभिर्विक्रियते स कदाचिद् अपि न शान्तिम् आप्नोति।'),
('ramanuja-sc:source:2.71','Rāmānuja','gita.2.71','sa','commentary','।।2.71।।काम्यन्ते इति कामाः शब्दादयो विषयाः। यः पुमान् शब्दादीन् सर्वान् विषयान् विहाय तत्र निःस्पृहः ममतारहितश्च अनात्मनि देहे आत्माभिमानरहितः चरति स आत्मानं दृष्ट्वा शान्तिम् अधिगच्छति।'),
('ramanuja-sc:source:2.72','Rāmānuja','gita.2.72','sa','commentary','।।2.72।। एषा नित्यात्मज्ञानपूर्विका असङ्गकर्मणि स्थितिः स्थितधीलक्षणा ब्राह्मी ब्रह्मप्रापिका। ईदृशीं कर्मस्थितिं प्राप्य न विमुह्यति न पुनः संसारम् आप्नोति। अस्यां स्थित्याम् अन्तिमे अपि वयसि स्थित्वा ब्रह्म निर्वाणम् ऋच्छति निर्वाणमयं ब्रह्म गच्छति सुखैकतानम् आत्मानम् आप्नोति इत्यर्थः।एवम् आत्मयाथात्म्यं युद्धाख्यस्य च कर्मणः तत्प्राप्तिसाधनताम् अजानतः शरीरात्मज्ञानेन मोहितस्य तेन च मोहेन युद्धात् निवृत्तस्य तन्मोहशान्तये नित्यात्मविषया सांख्यबुद्धिः तत्पूर्विका च असङ्गकर्मानुष्ठानरूपकर्मयोगविषया बुद्धिः स्थितप्रज्ञतायोगसाधनभूता द्वितीयेऽध्याये प्रोक्ता। तदुक्तम् नित्यात्मासङ्गकर्मेहागोचरा सांख्ययोगधीः। द्वितीये स्थितधीलक्ष्या प्रोक्ता तन्मोहशान्तये।। (गीतार्थसंग्रहे 6) इति।'),
('ramanuja-sc:source:3.1','Rāmānuja','gita.3.1','sa','commentary','।।3.1।।अर्जुन उवाच यदि कर्मणः बुद्धिः एव ज्यायसी इति ते मता किमर्थं तर्हि घोरे कर्मणि मां नियोजयसि एतदुक्तं भवतिज्ञाननिष्ठा एव आत्मावलोकनसाधनम् कर्मनिष्ठा तु तस्याः निष्पादिका आत्मावलोकनसाधनभूता च ज्ञाननिष्ठा सकलेन्द्रियमनसां शब्दादिविषयव्यापारोपरतिनिष्पाद्या इत्यभिहिता। इन्द्रियव्यापारोपरतिनिष्पाद्यम् आत्मावलोकनं चेद् सिषाधयिषितम् सकलकर्मनिवृत्तिपूर्वकज्ञाननिष्ठायाम् एव अहं नियोजयितव्यः किमर्थं घोरे कर्मणि सर्वेन्द्रियव्यापाररूपे आत्मावलोकनविरोधिनि कर्मणि मां नियोजयसि इति।'),
('ramanuja-sc:source:3.2','Rāmānuja','gita.3.2','sa','commentary','।।3.2।।अतो व्यामिश्रवाक्येन मां मोहयसि इव इति मे प्रतिभाति तथा हि आत्मावलोकनसाधनभूतायाः सर्वेन्द्रियव्यापारोपरतिरूपाया ज्ञाननिष्ठायाः तद्विपर्ययरूपं कर्म साधनं तद् एव कुरु इति वाक्यं विरुद्धं व्यामिश्रम् एव तस्माद् एकम् अमिश्ररूपं वाक्यं वद येन वाक्येन अहम् अनुष्ठेयरूपं निश्चित्य आत्मनः श्रेयः प्राप्नुयाम्।'),
('ramanuja-sc:source:3.3','Rāmānuja','gita.3.3','sa','commentary','।।3.3।।श्रीभगवानुवाच पुरा उक्तं च सम्यग् अवधृतं त्वया पुरा अपि अस्मिन् लोके विचित्राधिकारिसंपूर्णे द्विविधा निष्ठा ज्ञानकर्मविषया यथाधिकारम् असंकीर्णा एव मया उक्ता। न हि सर्वो लौकिकः पुरुषः संजातमोक्षाभिलाषः तदानीम् एव ज्ञानयोगाधिकारे प्रभवति अपि तु अनभिसंहितफलेन केवलपरमपुरुषाराधनरूपेण अनुष्ठितेन कर्मणा विध्वस्तमनोमलः अव्याकुलेन्द्रियो ज्ञाननिष्ठायाम् अधिकरोति यतः प्रवृत्तिर्भूतानां येन सर्वमिदं ततम्। स्वकर्मणा तमभ्यर्च्य सिद्धिं विन्दति मानवः।।(गीता 18।46)इति परमपुरुषाराधनैकवेषता कर्मणां वक्ष्यते।इहापिकर्मण्येवाधिकारस्ते (गीता 2।47) इत्यादिना अनभिसंहितफलं कर्म अनुष्ठेयं विधाय तेन विषयव्याकुलतारूपमोहाद् उत्तीर्णबुद्धेःप्रजहाति यदा कामान् (गीता 2।55) इत्यादिना ज्ञानयोग उदितः। अतः सांख्यानाम् एव ज्ञानयोगेन स्थितिः उक्ता योगिनां तु कर्मयोगेन।संख्या बुद्धिः तद्युक्ताः सांख्याः आत्मैकविषयया बुद्ध्या युक्ताः सांख्याः अतदर्हाः कर्मयोगाधिकारिणो योगिनः। विषयव्याकुलबुद्धियुक्तानां कर्मयोगे अधिकारः अव्याकुलबुद्धीनां तु ज्ञानयोगे अधिकार उक्तः सति न किञ्चिद् इह विरुद्धम् न अपि व्यामिश्रम् अभिहितम्।सर्वस्य लौकिकस्य पुरुषस्य मोक्षेच्छायां संजातायां सहसा एव ज्ञानयोगो दुष्कर इत्याह'),
('ramanuja-sc:source:3.4','Rāmānuja','gita.3.4','sa','commentary','।।3.4।।न शास्त्रीयाणां कर्मणाम् अनारम्भाद् एव पुरुषः नैष्कर्म्यं ज्ञाननिष्ठाम् आप्नोति सर्वेन्द्रियव्यापाराख्यकर्मोपरतिपूर्विकां ज्ञाननिष्ठां न प्राप्नोति इत्यर्थः। न च आरब्धस्य शास्त्रीयस्य कर्मणः त्यागात् यतः अनभिसंहितफलस्य परमपुरुषाराधनविषयस्य कर्मणः सिद्धिः आत्मनिष्ठा स्यात् अतः तेन विना तां न प्राप्नोति अनभिसंहितफलैः कर्मभिः अनाराधितगोविन्दैः अविनष्टानादिकालप्रवृत्तानन्तपापसंचयैः अव्याकुलेन्द्रियतापूर्विका आत्मनिष्ठा दुःसंपाद्या।एतद् एव उपपादयति'),
('ramanuja-sc:source:3.5','Rāmānuja','gita.3.5','sa','commentary','।।3.5।।न हि अस्मिन् लोके वर्तमानः पुरुषः कश्चित् कदाचित् अपि कर्म अकुर्वाणः तिष्ठति।न किञ्चित्करोमि इति व्यवसितः अपि सर्वः पुरुषः प्रकृतिसमुद्भवैः सत्त्वरजस्तमोभिः प्राक्तनकर्मानुगुणं प्रवृद्धैः गुणैः स्वोचितं कर्म प्रति अवशः कार्यते प्रवर्त्यते। अत उक्तलक्षणेन कर्मयोगेन प्राचीनं पापसञ्चयं नाशयित्वा गुणांश्च सत्त्वादीन् वशे कृत्वा निर्मलान्तःकरणेन संपाद्यो ज्ञानयोगः।अन्यथा ज्ञानयोगाय प्रवृत्तः अपि मिथ्याचारो भवति इति आह'),
('ramanuja-sc:source:3.6','Rāmānuja','gita.3.6','sa','commentary','।।3.6।।अविनष्टपापतया अजितबाह्यान्तःकरण आत्मज्ञानाय प्रवृत्तो विषयप्रवणतया आत्मनि विमुखीकृतमनाः विषयान् एव स्मरन् य आस्ते अन्यथा संकल्प्य अन्यथा चरति इति स मिथ्याचारः उच्यते आत्मज्ञानाय उद्युक्तो विपरीतो विनष्टो भवति इत्यर्थः।'),
('ramanuja-sc:source:3.7','Rāmānuja','gita.3.7','sa','commentary','।।3.7।।अतः पूर्वाभ्यस्तविषयसजातीये शास्त्रीये कर्मणि इन्द्रियाणि आत्मावलोकनप्रवृत्तेन मनसा नियम्य तैः स्वत एव कर्मप्रवणैः इन्द्रियैः असङ्गपूर्वकं यः कर्मयोगम् आरभते सः असंभाव्यमानप्रमादत्वेन ज्ञाननिष्ठाद् अपि पुरुषाद् विशिष्यते।'),
('ramanuja-sc:source:3.8','Rāmānuja','gita.3.8','sa','commentary','।।3.8।। नियतं व्याप्तम् प्रकृतिसंसृष्टेन हि व्याप्तं कर्म प्रकृतिसंसृष्टत्वम् अनादिवासनया। नियतत्वेन सुशकत्वाद् असंभावितप्रमादत्वाच्च कर्मणः कर्म एव कुरु अकर्मणः ज्ञाननिष्ठाया अपि कर्म एव ज्यायः नैष्कर्म्यं पुरुषोऽश्नुते (गीता 3।4) इति प्रक्रमात् अकर्मशब्देन ज्ञाननिष्ठा एव उच्यतेज्ञाननिष्ठाधिकारिणः अपि अनभ्यस्तपूर्वतया हि अनियतत्वेन दुःशकत्वात् सप्रमादत्वाच्च ज्ञाननिष्ठायाः कर्मनिष्ठा एव ज्यायसी।कर्मणि क्रियमाणे च आत्मयाथात्म्यज्ञानेन आत्मनः अकर्तृत्वानुसंधानम् अनन्तरम् एव वक्ष्यते अत आत्मज्ञानस्य अपि कर्मयोगान्तर्गतत्वात् स एव ज्यायान् इत्यर्थः।कर्मणो ज्ञाननिष्ठाया ज्यायस्त्ववचनं ज्ञाननिष्ठायाम् अधिकारे सति एव उपपद्यते। यदि सर्वं कर्म परित्यज्यकेवलं ज्ञाननिष्ठायाम् अधिकरोषि तर्हि अकर्मणः ते ज्ञाननिष्ठस्य ज्ञाननिष्ठोपकारिणी शरीरयात्रा अपि न सेत्स्यति।यावत्साधनसमाप्ति शरीरधारणं च अवश्यं कार्यम् न्यायार्जितधनेन महायज्ञादिकं कृत्वा तच्छिष्टाशनेन एव शरीरधारणं कार्यम्आहारशुद्धौ सत्त्वशुद्धिः सत्त्वशुद्धौ ध्रुवा स्मृतिः। (छा0 उ0 7।26।2) इत्यादिश्रुतेः।भुञ्जते ते त्वघं पापाः (गीता 3।13) इति च वक्ष्यते। अतो ज्ञाननिष्ठस्य अपि कर्म अकुर्वतो देहयात्रा न सेत्स्यति।यतो ज्ञाननिष्ठस्य अपि ध्रियमाणशरीरस्य यावत्साधनसमाप्ति महायज्ञादिनित्यनैमित्तिकं कर्म अवश्यं कार्यम्। यतश्च कर्मयोगे अपि आत्मनः अकर्तृत्वभावनया आत्मयाथात्म्यानुसन्धानम् अन्तर्भूतम् यतश्च प्रकृतिसंसृष्टस्य कर्मयोगः सुशकः अप्रमादश्च अतो ज्ञाननिष्ठायोग्यस्य अपि ज्ञानयोगात् कर्मयोगो ज्यायान्। तस्मात् त्वं कर्मयोगम् एव कुरु इत्यभिप्रायः।एवं तर्हि द्रव्यार्जनादेः कर्मणः अहङ्कारममकारादिसर्वेन्द्रियव्याकुलतागर्भत्वेन अस्य पुरुषस्य कर्मवासनया बन्धनं भविष्यति इति अत्र आह'),
('ramanuja-sc:source:3.9','Rāmānuja','gita.3.9','sa','commentary','।।3.9।।यज्ञादिशास्त्रीयकर्मशेषभूताद् द्रव्यार्जनादेः कर्मणः अन्यत्र आत्मीयप्रयोजनशेषभूते कर्मणि क्रियमाणे अयं लोकः कर्मबन्धनो भवति। अतः त्वं यज्ञाद्यर्थं द्रव्यार्जनादिकं कर्म समाचर तत्र आत्मप्रयोजनसाधनतया यः सङ्गः तस्मात् सङ्गात् मुक्तः सन् समाचर।एवं मुक्तसङ्गेन यज्ञाद्यर्थतया कर्मणि क्रियमाणे यज्ञादिभिः कर्मभिः आराधितः परमपुरुषः अस्य अनादिकालप्रवृत्तकर्मवासनां समुच्छिद्य अव्याकुलात्मावलोकनं ददाति इत्यर्थः।यज्ञशिष्टेन एव सर्वपुरुषार्थसाधननिष्ठानां शरीरधारणकर्तव्यताम् अयज्ञशिष्टेन शरीरधारणं कुर्वतां दोषं च आह'),
('ramanuja-sc:source:3.10','Rāmānuja','gita.3.10','sa','commentary','।।3.10।।पतिं विश्वरस्य आत्मेश्वरम् (तै0 ना0 11।3) इत्यादिश्रुतेः निरुपाधिकः प्रजापतिशब्दः सर्वेश्वरं विश्वस्रष्टारं विश्वात्मानं परायणं नारायणम् आह पुरा सर्गकाले स भगवान् प्रजापतिः अनादिकालप्रवृत्ताचित्संसर्गविवशा उपसंहृतनामरूपविभागाः स्वस्मिन् प्रलीनाः सकलपुरुषार्थनर्हाः चेतनेतरकल्पाः प्रजाः समीक्ष्य परमकारुणिकः तदुज्जिजीवविषया स्वाराधनभूतयज्ञनिर्वृत्तये यज्ञैः सह ताः सृष्ट्वा एवम् उवाच अनेन यज्ञेन प्रसविष्यध्वम् आत्मनो वृद्धिं कुरुध्वम्। एष वो यज्ञः परमपुरुषार्थलक्षणमोक्षाख्यस्य कामस्य तदनुगुणानां च कामानां प्रपूरयिता भवतु।कथम्'),
('ramanuja-sc:source:3.11','Rāmānuja','gita.3.11','sa','commentary','।।3.11।।अनेन देवताराधनभूतेन देवान् मच्छरीरभूतान् मदात्मकान् आराधयतअहं हि सर्वयज्ञानां भोक्ता च प्रभुरेव च (गीता 9।24) इति वक्ष्यते। यज्ञेन आराधिताः ते देवा मदात्मकाः स्वाराधनापेक्षितान्नपानाद्यैः युष्मान् पुष्णन्तु। एवं परस्परं भावयन्तः परं श्रेयो मोक्षाख्यम् अवाप्स्यथ।'),
('ramanuja-sc:source:3.12','Rāmānuja','gita.3.12','sa','commentary','।।3.12।।यज्ञभाविताः यज्ञेन आराधिताः मदात्मका देवा इष्टान् भोगान् वो दास्यन्ते परमपुरुषार्थलक्षणं मोक्षं साधयतां ये इष्टा भोगाः तान् पूर्वपूर्वयज्ञभाविता देवा दास्यन्ते। उत्तरोत्तराराधनापेक्षितान् सर्वान् भोगान् वो दास्यन्ति इत्यर्थः।स्वाराधनार्थता तैः दत्तान् भोगान् तेभ्यः अप्रदाय यो भुङ्क्ते चोर एव सः। चौर्यं हि नाम अन्यदीये तत्प्रयोजनाय एव परिक्लृप्ते वस्तुनि स्वकीयताबुद्धिं कृत्वा तेन स्वात्मपोषणम्। अतः अस्य न परमपुरुषार्थानर्हतामात्रम् अपि तु निरयगामित्वं च भविष्यति इत्यभिप्रायः।तद् एव विवृणोति'),
('ramanuja-sc:source:3.13','Rāmānuja','gita.3.13','sa','commentary','।।3.13।।इन्द्राद्यात्मना अवस्थितपरमपुरुषाराधनार्थतया एव द्रव्याणि उपादाय विपच्य तैः यथावस्थितं परमपुरुषम् आराध्य तच्छिष्टाशनेन ये शरीरयात्रां कुर्वते ते तु अनादिकालोपार्जि तैः किल्बिषैः आत्मयाथात्म्यावलोकनविरोधिभिः सर्वैः विमुच्यन्ते।ये तु परमपुरुषेण इन्द्राद्यात्मना स्वाराधनाय दत्तानाम् आत्मार्थतया उपादाय विपच्य अश्नन्ति ते पापात्मानः अघम् एव भुञ्जते। अघपरिणामित्वाद् अघम् इति उच्यते। आत्मावलोकनविमुखा नरकाय एव पच्यन्ते।पुनरपि लोकदृष्ट्या शास्त्रदृष्ट्या च सर्वस्य यज्ञमूलत्वं दर्शयित्वा यज्ञानुवर्तनस्य अवश्यकार्यताम् अननुवर्तने च दोषं च आह'),
('ramanuja-sc:source:3.14','Rāmānuja','gita.3.14','sa','commentary','।।3.14।।अन्नात् सर्वाणि भूतानि भवन्ति पर्जन्याद् अन्नसंभवः इति सर्वलोकसाक्षिकम्। यज्ञात् पर्जन्यो भवति इति च शास्त्रेण अवगम्यते अग्नौ प्रास्ताहुतिः सम्यगादित्यमुपतिष्ठते। आदित्याज्जायते वृष्टिर्वृष्टेरन्नं ततः प्रजाः।। (मनु0 3।76) इत्यादिना। यज्ञः च द्रव्यार्जनादिकर्तृपुरुषव्यापाररूपकर्मसमुद्भवः।'),
('ramanuja-sc:source:3.15','Rāmānuja','gita.3.15','sa','commentary','।।3.15।।कर्म ब्रह्मोद्भवम्। अत्र च ब्रह्मशब्दनिर्दिष्टं प्रकृतिपरिणामरूपशरीरम्तस्मादेतद् ब्रह्म नाम रूपमन्नं च जायते (मु0 1।1।9) इति ब्रह्मशब्देन प्रकृतिः निर्दिष्टा। इहापिमम योनिर्महद्ब्रह्म (गीता 14।3) इति वक्ष्यते। अतः कर्म ब्रह्मोद्भवम् इति प्रकृतिपरिणामरूपशरीरोद्भवं कर्म इत्युक्तं भवति। ब्रह्म अक्षरसमुद्भवम् इत्यत्र अक्षरशब्दनिर्दिष्टो जीवात्मा अन्नपानादिना तृप्ताक्षराधिष्ठितं शरीरं कर्मणे प्रभवति इति कर्मसाधनभूतं शरीरम् अक्षरसमुद्भवम्। तस्मात् सर्वगतं ब्रह्म सर्वाधिकारिगतं शरीरं नित्यं यज्ञे प्रतिष्ठितम् यज्ञमूलम् इत्यर्थः।'),
('ramanuja-sc:source:3.16','Rāmānuja','gita.3.16','sa','commentary','।।3.16।।एवं परमपुरुषेण प्रवर्तितम् इदं चक्रम्अन्नाद् भवन्ति भूतानि इत्यत्र भूतशब्दनिर्दिष्टानि सजीवानि शरीराणि। पर्जन्यादन्नम् यज्ञात् पर्जन्यः यज्ञश्च कर्तृव्यापारानुरूपात् कर्मणः कर्म च सजीवात् शरीरात् सजीवं शरीरं च पुनरन्नाद् इति अन्योन्यकार्यकारणभावेन चक्रवत् परिवर्तमानम् इह साधने वर्तमानो यः कर्मयोगाधिकारी ज्ञानयोगाधिकारी वा न अनुवर्तयति न प्रवर्तयति यज्ञशिष्टेन देहधारणम् अकुर्वन् सः अघायुः भवति अघारम्भाय एव अस्य आयुः अघपरिणतं वा उभयरूपं वा सः अघायुः।अत एव इन्द्रियारामो भवति न आत्मारामः इन्द्रियाणि एव अस्य उद्यानानि भवन्ति अयज्ञशिष्टवर्द्धितदेहमनस्त्वेन उद्रिक्तरजस्तमस्कः आत्मावलोकनविमुखतया विषयभोगैकरतिः भवति अतो ज्ञानयोगादौ यतमानः अति निष्फलप्रयत्नतया मोघं पार्थ स जीवति।असाधनायत्तात्मदर्शनस्य मुक्तस्य एव महायज्ञादिवर्णाश्रमोचितकर्मानारम्भ इत्याह'),
('ramanuja-sc:source:3.17','Rāmānuja','gita.3.17','sa','commentary','।।3.17।।यः तु ज्ञानयोगकर्मयोगसाधननिरपेक्षः स्वत एव आत्मरतिः आत्माभिमुखः आत्मना एव तृप्तः न अन्नपानादिभिः आत्मव्यतिरिक्तैः आत्मनि एव च सन्तुष्टः न उद्यानस्रक्चन्दनगीतवादित्रनृत्यादौ धारणपोषणभोग्यादिकं सर्वम् आत्मा एव यस्य तस्य आत्मदर्शनाय कर्तव्यं न विद्यते स्वत एव सर्वदा दृष्टात्मस्वरूपत्वात्।'),
('ramanuja-sc:source:3.18','Rāmānuja','gita.3.18','sa','commentary','।।3.18।।अत एव तस्य आत्मदर्शनाय कृतेन तत्साधनेन न अर्थः न किञ्चित् प्रयोजनम् अकृतेन आत्मदर्शनसाधनेन न कश्चिद् अनर्थः असाधनायत्तात्मदर्शनत्वात्। स्वत एवात्मव्यतिरिक्तसकलाचिद्वस्तुविमुखस्य अस्य सर्वेषु प्रकृतिपरिणामविशेषेषु आकाशादिषु भूतेषु सकार्येषु न कश्चित् प्रयोजनतया साधनतया वा व्यपाश्रयः यतः तद्विमुखीकरणाय साधनारम्भः स हि मुक्त एव।यस्माद् असाधनायत्तात्मदर्शनस्य एव साधनाप्रवृत्तिः यस्मात् च साधने प्रवृत्तस्य अपि सुशकत्वाद् अप्रमादत्वात् तदन्तर्गतात्मयाथात्म्यानुसन्धानत्वाद् च ज्ञानयोगिनः अपि देहयात्रायाः कर्मानुवृत्त्यपेक्षत्वात् च कर्मयोग एव आत्मदर्शननिर्वृत्तौ श्रेयान्'),
('ramanuja-sc:source:3.19','Rāmānuja','gita.3.19','sa','commentary','।।3.19।।तस्माद् असङ्गपूर्वकं कार्यम् इत्येव सततं यावदात्मप्राप्ति कर्म एव समाचर। असक्तः कार्यम् इति वक्ष्यमाणाकर्तृत्वानुसन्धानपूर्वकं च कर्म अनुचरन् पूरुषः कर्मयोगेन एव परम् आप्नोति आत्मानं प्राप्नोति इत्यर्थः।'),
('ramanuja-sc:source:3.20','Rāmānuja','gita.3.20','sa','commentary','।।3.20।।यतो ज्ञानयोगाधिकारिणः अपि कर्मयोग एव आत्मदर्शने श्रेयान् अत एव हि जनकादयो राजर्षयो ज्ञानिनाम् अग्रेसराः कर्मयोगेन एव संसिद्धिम् आस्थिताः आत्मानं प्राप्तवन्तः।एवं प्रथमं मुमुक्षोः ज्ञानयोगानर्हतया कर्मयोगाधिकारिणः कर्मयोग एव कार्यः इत्युक्त्वा ज्ञानयोगाधिकारिणः अपि ज्ञानयोगात् कर्मयोग एव श्रेयान् इति सहेतुकम् उक्तम्। इदानीं शिष्टतया व्यपदेश्यस्य सर्वथा कर्मयोग एव कार्य इति उच्यते लोकसंग्रहं पश्यन् अपि कर्म एव कर्तुम् अर्हसि।'),
('ramanuja-sc:source:3.21','Rāmānuja','gita.3.21','sa','commentary','।।3.21।।श्रेष्ठः कृत्स्नशास्त्रज्ञातृतया अनुष्ठातृतया च प्रथितो यद् यद् आचरति तत् तद् एव अकृत्स्नविद् जनः अपि आचरति। अनुष्ठीयमानम् अपि कर्म श्रेष्ठो यत्प्रमाणं यदङ्गयुक्तम् अनुतिष्ठति तदङ्गयुक्तम् एव अकृत्स्नविद् लोकः अपि अनुतिष्ठति अतो लोकरक्षार्थं शिष्टतया प्रथितेन श्रेष्ठेन स्ववर्णाश्रमोचितं कर्म सकलं सर्वदा अनुष्ठेयम्। अन्यथा लोकनाशजनितं पापं ज्ञानयोगाद् अपि एनं प्रच्यावयेत्।'),
('ramanuja-sc:source:3.22','Rāmānuja','gita.3.22','sa','commentary','।।3.22।।न मे सर्वेश्वरस्य अवाप्तसमस्तकामस्य सर्वज्ञस्य सत्यसंकल्पस्य त्रिषु लोकेषु देवमनुष्यादिरूपेण स्वच्छन्दतो वर्तमानस्य किञ्चिद् अपि कर्तव्यम् अस्ति यतः अनवाप्तं कर्मणा अवाप्तव्यं न किञ्चिद् अपि अस्ति अथापि लोकरक्षायै कर्मणि एव वर्ते।'),
('ramanuja-sc:source:3.23','Rāmānuja','gita.3.23','sa','commentary','।।3.23।।अह सर्वेश्वरः सत्यसंकल्पः स्वसंकल्पकृतजगदुदयविभवलयलीलः स्वच्छन्दतो जगदुपकृतये मर्त्यो जातः अपि मनुष्येषु शिष्टजनाग्रेसरवसुदेवगृहे अवतीर्णः तत्कुलोचिते कर्मणि अतन्द्रितः सर्वदा यदि न वर्तेयम् मम शिष्टजनाग्रेसरवसुदेवसूनोः वर्त्म अकृत्स्नविदः शिष्टाः च सर्वप्रकारेणअयम् एव धर्मः इति अनुवर्तन्ते ते च स्वकर्तव्याननुष्ठानेन अकरणे प्रत्यवायेन च आत्मानम् अनुपलभ्य निरयगामिनो भवेयुः।'),
('ramanuja-sc:source:3.24','Rāmānuja','gita.3.24','sa','commentary','।।3.24।।अहं कुलोचितं कर्म न चेत् कुर्याम् एवम् एव सर्वे शिष्टलोका मदाचारायत्तधर्मनिश्चया अकरणाद् एव उत्सीदेयुः नष्टा भवेयुः शास्त्रीयाचाराणाम् अपालनात् सर्वेषां शिष्टकुलानां संकरस्य च कर्ता स्याम् अता एव इमाः प्रजा उपहन्याम्। एवम् एव त्वम् अपि शिष्टजनाग्रेसरपाण्डुतनयः युधिष्ठिरानुजः अर्जुनः सन् शिष्टतया यदि ज्ञाननिष्ठायाम् अधिकरोषि ततः त्वदाचारानुवर्तिनः अकृत्स्नविदः शिष्टाः च मुमुक्षवः स्वाधिकारम् अजानन्तः कर्मनिष्ठायाम् अनधिकुर्वन्तो विनश्येयुः अतो व्यपदेश्येन विदुषा कर्म एव कर्तव्यम्।'),
('ramanuja-sc:source:3.25','Rāmānuja','gita.3.25','sa','commentary','।।3.25।।अविद्वांसः आत्मनि अकृत्स्नविदः कर्मणि सक्ताः कर्मणि अवर्जनीयसंबन्धाः आत्मनि अकृत्स्नवित्तया तदभ्यासरूपज्ञानयोगे अनधिकृताः कर्मयोगाधिकारणिः कर्मयोगम् एव यथा आत्मदर्शनाय कुर्वते तथा आत्मनि कृत्स्नवित्तया कर्मणि असक्तः ज्ञानयोगाधिकारयोग्यः अपि व्यपदेश्यः शिष्टः लोकरक्षणार्थं स्वाचारेण शिष्टलोकानां धर्मनिश्चयं चिकीर्षुः कर्मयोगम् एव कुर्यात्।'),
('ramanuja-sc:source:3.26','Rāmānuja','gita.3.26','sa','commentary','।।3.26।।अज्ञानाम् आत्मन्यकृत्स्नवित्तया ज्ञानयोगोपादानाशक्तानां मुमुक्षूणां कर्मसङ्गिनाम् अनादिकर्मवासनया कर्मणि एव नियतत्वेन कर्मयोगाधिकारिणांकर्मयोगाद् अन्यथात्मावलोकनम् अस्ति इति न बुद्धिभेदं जनयेत्। किं तर्हि आत्मनि कृत्स्नवित्तया ज्ञानयोगशक्तः अपि पूर्वोक्तरीत्याकर्मयोग एव ज्ञानयोगनिरपेक्ष आत्मावलोकनसाधनम् इति बुद्ध्या युक्तः कर्म एव आचरन् सर्वकर्मसु अकृत्स्नविदां प्रीतिं जनयेत्।अथ कर्मयोगम् अनुतिष्ठतो विदुषः अविदुषश्च विशेषं प्रदर्शयन् कर्मयोगापेक्षितम् आत्मनः अकर्तृत्वानुसन्धानप्रकारम् उपदिशति'),
('ramanuja-sc:source:3.27','Rāmānuja','gita.3.27','sa','commentary','।।3.27।।प्रकृतेः गुणैः सत्त्वादिभिः स्वानुरूपं क्रियमाणानि कर्माणि प्रति अहंकारविमूढात्मा अहं कर्ता इति मन्यते। अहंकारेण विमूढ आत्मा यस्य असौ अहंकारविमूढात्मा अहंकारो नाम अनहमर्थे प्रकृतौ अहम् इति अभिमानः तेन अज्ञातात्मस्वरूपो गुणकर्मसु अहं कर्ता इति मन्यते इत्यर्थः।'),
('ramanuja-sc:source:3.28','Rāmānuja','gita.3.28','sa','commentary','।।3.28।।गुणकर्मविभागयोः सत्त्वादिगुणविभागे तत्तत्कर्मविभागे च तत्त्ववित् गुणाः सत्त्वादयः स्वगुणेषु स्वेषु कार्येषु वर्तन्ते इति मत्वा गुणकर्मसु अहं कर्ता इति न सज्जते।'),
('ramanuja-sc:source:3.29','Rāmānuja','gita.3.29','sa','commentary','।।3.29।।अकृत्स्नविदः तु आत्मदर्शनाय प्रवृत्ताः प्रकृतिसंसृष्टतया प्रकृतेः गुणैः यथावस्थितात्मनि संमूढाः गुणकर्मसु क्रियासु एव सज्जन्ते न तद्विविक्तात्मस्वरूपे अतः ते ज्ञानयोगाय न प्रभवन्ति इति कर्मयोगे एव तेषाम् अधिकारः। एवंभूतान् तान् मन्दान् अकृत्स्नविदः कृत्स्नवित् स्वयं ज्ञानयोगावस्थानेन न विचालयेत्। ते किल मन्दाः श्रेष्ठजनाचारानुवर्तिनः कर्मयोगाद् उत्थितम् एनं दृष्ट्वा कर्मयोगात् प्रचलितमनसो भवेयुः। अतः श्रेष्ठः स्वयम् अपि कर्मयोगे तिष्ठन् आत्मयाथात्म्यज्ञानेन आत्मनः अकर्तृत्वम् अनसन्दधानःकर्मयोग एव आत्मावलोकने निरपेक्षसाधनम् इति दर्शयित्वा तान् अकृत्स्नविदो मन्दान् जोषयेद् इत्यर्थः।ज्ञानयोगाधिकारिणः अपि ज्ञानयोगाद् अस्य एव कर्मयोगस्य ज्यायस्त्वं पूर्वम् एव उक्तम्। अतो व्यपदेश्यो लोकसंग्रहाय कर्म एव कुर्यात्। प्रकृतिविविक्तात्मस्वभावनिरूपणेन गुणेषु कर्तृत्वम् आरोप्य कर्मानुष्ठानप्रकार उक्तः। गुणेषु कर्तृत्वानुसन्धानं च इदम् एवआत्मनो न स्वरूपप्रयुक्तम् इदम् कर्तृत्वम् अपि तु गुणसम्बन्धकृतम् इति प्राप्ताप्राप्तविवेकेन गुणकृतम् इति अनुसन्धानम्।इदानीम् आत्मनां परमपुरुषशरीरतया तन्नियाम्यत्वस्वरूपनिरूपणेन भगवति पुरुषोत्तमे सर्वात्मभूते गुणकृतं च कर्तृत्वम् आरोप्य कर्मकर्तव्यतया उच्यते'),
('ramanuja-sc:source:3.30','Rāmānuja','gita.3.30','sa','commentary','।।3.30।।मयि सर्वेश्वरे सर्वभूतान्तरात्मभूते सर्वाणि कर्माणि अध्यात्मचेतसा संन्यस्य निराशीः निर्ममो विगतज्वरः युद्धादिकं सर्वं चोदितं कर्म कुरुष्व। आत्मनि यत् चेतः तद् अध्यात्मचेतः आत्मस्वरूपविषयेण श्रुतिशतसिद्धेन ज्ञानेन इत्यर्थः।अन्तः प्रविष्टः शास्ता जनानां सर्वात्मा ৷৷. अन्तः प्रविष्टं कर्तारमेतम् (तै0 आ0 3।11)य आत्मनि तिष्ठन्नात्मनोऽन्तरो यमात्मा न वेद। यस्यात्मा शरीरं य आत्मानमन्तरो यमयति स त आत्मान्तर्याम्यमृतः (बृ0 5।7 मा0 दि0) इत्येवमाद्याः श्रुतयः परमपुरुषप्रवर्त्यं तच्छरीरभूतम् एनम् आत्मानं परमपुरुषं च प्रवर्तयितारम् आचक्षते। स्मृतयश्च प्रशासितारं सर्वेषाम् (मनु0 12।122) इत्याद्याःसर्वस्य चाहं हृदि सन्निविष्टः (गीता 15।15) ईश्वरः सर्वभूतानां हृद्देशेऽर्जुन तिष्ठति। भ्रामयन् सर्वभूतानि यन्त्रारूढानि मायया।।(गीता 18।61) इति वक्ष्यते।अतो मच्छरीरतया मत्प्रवर्त्यात्मस्वरूपानुसन्धानेन सर्वाणि कर्माणि मया एव क्रियमाणानि इति मयि परमपुरुषे संन्यस्य तानि च केवलं मदाराधनानि इति कृत्वा तत्फले निराशीः तत एव तत्र कर्मणि ममतारहितो भूत्वाविगतज्वरो युद्धादिकं कुरुष्व।स्वकीयेन आत्मना कर्त्रा स्वकीयैः एव करणैः स्वाराधनैकप्रयोजनाय परमपुरुषः सर्वेश्वरः सर्वशेषी स्वयम् एव स्वकर्माणि कारयति इति अनुसन्धाय कर्मसु ममतारहितः प्राचीनेन अनादिकालप्रवृत्तानन्तपापसञ्चयेनकथम् अहं भविष्यामि इत्येवं भूतान्तर्ज्वरविनिर्मुक्तःपरमपुरुष एव कर्मभिः आराधितो बन्धात् मोचयिष्यति इति स्मरन् सुखेन कर्मयोगम् एव कुरुष्व इत्यर्थः।तमीश्वराणां परमं महेश्वरं तं देवतानां परमं च दैवतम्। (श्ेवता 3।7)पतिं विश्वस्य (म0 ना0 3।1)पतिं पतीनाम् (श्वेता 6।7) इत्यादिश्रुतिसिद्धं हि सर्वेश्वरत्वं सर्वशेषित्वं च। ईश्वरत्वं नियन्तृत्वम् शेषित्वं पतित्वम्।।अयम् एव साक्षादुपनिषत्सारभूतः अर्थ इत्याह'),
('ramanuja-sc:source:3.31','Rāmānuja','gita.3.31','sa','commentary','।।3.31।।ये मानवाः आत्मनिष्ठशास्त्राधिकारिणःअयम् एव शास्त्रार्थः इत्येतत् मे मतं निश्चित्य तथा अनुतिष्ठन्ति ये च अननुतिष्ठन्तः अपि अस्मिन् शास्त्रार्थे श्रद्दधाना भवन्ति ये च अश्रद्दधाना अपिएवं शास्त्रार्थो न संभवति इति न अभ्यसूयन्ति अस्मिन् महागुणे शास्त्रार्थे दोषदर्शिनो न भवन्ति इत्यर्थः ते सर्वे बन्धहेतुभिः अनादिकालप्रारब्धैः कर्मभिः मुच्यन्ते। ते अपि कर्मभिः इति अपिशब्दाद् एषां पृथक्करणम्। इदानीम् अननुतिष्ठन्तः अपि अस्मिन् शास्त्रार्थे श्रद्दधाना अनभ्यसूयवः च श्रद्धया च अनसूयया च क्षीणपापा अचिरेण इमम् एव शास्त्रार्थम् अनुष्ठाय मुच्यन्ते इत्यर्थः।भगवदभिमतम् औपनिषद्म् अर्थम् अननुतिष्ठताम् अश्रद्दधानानाम् अभ्यसूयतां च दोषम् आह'),
('ramanuja-sc:source:3.32','Rāmānuja','gita.3.32','sa','commentary','।।3.32।।ये तु एतत् सर्वम् आत्मवस्तु मच्छरीरतया मदाधारं मच्छेषभूतं मदेकप्रवर्त्त्यम् इति मे मतं न अनुतिष्ठन्ति न एवम् अनुसन्धाय सर्वाणि कर्माणि कुर्वते ये च न श्रद्दधते ये च अभ्यसूयन्तो वर्तन्ते तान् सर्वेषु ज्ञानेषु विशेषेण मूढान् तत एव नष्टान् अचेतसो विद्धि। चेतःकार्यं हि वस्तुयाथात्म्यनिश्चयः तदभावाद् अचेतसः विपरीतज्ञानाः सर्वत्र विमूढाश्च।एवं प्रकृतिसंसर्गिणः तद्गुणोद्रेककृतं कर्तृत्वं तच्च परमपुरुषायत्तम् इति अनुसन्धाय कर्मयोगयोग्येन ज्ञानयोगयोग्येन च कर्मयोगस्य सुशकत्वाद् अप्रमादत्वाद् अन्तर्गतात्मज्ञानतया निरपेक्षत्वाद् इतरस्य दुःशकत्वात् सप्रमादत्वात् शरीरधारणाद्यर्थतया कर्मापेक्षत्वात् कर्मयोग एव कर्तव्यः। व्यपदेश्यस्य तु विशेषतः स एव कर्तव्य इति च उक्तम्। अतः परम् अध्यायशेषेण ज्ञानयोगस्य दुःशकतया सप्रमादता उच्यते'),
('ramanuja-sc:source:3.33','Rāmānuja','gita.3.33','sa','commentary','।।3.33।।प्रकृतिविविक्तम् ईदृशम् आत्मस्वरूपम् तदेव सर्वदानुसन्धेयम् इति च शास्त्राणि प्रतिपादयन्ति इति ज्ञानवान् अपि स्वस्याः प्रकृतेः प्राचीनवासनायाः सदृशं प्राकृतविषयेषु एव चेष्टते कुतः प्रकृतिं यान्ति भूतानि अचित्संसृष्टा जन्तवः अनादिकालप्रवृत्तवासनाम् एव यान्ति तानि वासनानुयायीनि भूतानि शास्त्रकृतो निग्रहः किं करिष्यति।प्रकृत्यनुयायित्वप्रकारम् आह'),
('ramanuja-sc:source:3.34','Rāmānuja','gita.3.34','sa','commentary','।।3.34।।श्रोत्रदिज्ञानेन्द्रियस्य अर्थे शब्दादौ वागादिकर्मेन्द्रियस्य च अर्थे वचनादौ प्राचीनवासनाजनिततदनुबुभूषारूपो रागः अवर्जनीयो व्यवस्थितः तदनुभवे प्रतिहते च अवर्जनीयो द्वेषो व्यवस्थितः तौ एव ज्ञानयोगाय यतमानं नियमितसर्वेन्द्रियं स्ववशे कृत्वा प्रसह्य स्वकार्येषु नियोजयतः। ततः च अयम् आत्मस्वरूपानुभवविमुखो विनष्टो भवति। तयोः न वशम् आगच्छेत् ज्ञानयोगारम्भेण रागद्वेषवशम् आगम्य न विनश्येत्। तौ रागद्वेषौ हि अस्य दुर्जयौ शत्रू आत्मज्ञानाभ्यासं वारयतः।'),
('ramanuja-sc:source:3.35','Rāmānuja','gita.3.35','sa','commentary','।।3.35।।अतः सुशकतया स्वधर्मभूतः कर्मयोगो विगुणः अपि अप्रमादगर्भः प्रकृतिसंसृष्टस्य दुःशकतयापरधर्मभूतात् ज्ञानयोगात् सगुणाद् अपि किञ्चित्कालम् अनुष्ठितात् सप्रमादात् श्रेयान्।स्वेन एव उपादातुं योग्यतया स्वधर्मभूते कर्मयोगे वर्तमानस्य एकस्मिन् जन्मनि अप्राप्तफलतया निधनम् अपि श्रेयः अनन्तरायहततया अनन्तरजन्मनि अपि अव्याकुलकर्मयोगारम्भसंभवात्। प्रकृतिसंसृष्टस्य स्वेन एव उपादातुम् अशक्यतया परधर्मभूतो ज्ञानयोगः प्रमादगर्भतया भयावहः।'),
('ramanuja-sc:source:3.36','Rāmānuja','gita.3.36','sa','commentary','।।3.36।।अर्जुन उवाच अथ अयं ज्ञानयोगाय प्रवृत्तः पूरुषः स्वयं विषयान् अनुभवितुम् अनिच्छन् अपि केन प्रयुक्तो विषयानुभवरूपं पापं बलात् नियोजित इव चरति।'),
('ramanuja-sc:source:3.37','Rāmānuja','gita.3.37','sa','commentary','।।3.37।।श्रीभगवानुवाच अस्य उद्भवाभिभवरूपेण वर्तमानगुणमयप्रकृतिसंसृष्टस्य प्रारब्धज्ञानयोगस्य रजोगुणसमुद्भवः प्राचीनवासनाजनितः शब्दादिविषयः अयं कामो महाशनः शत्रुः सर्वविषयेषु एनम् आकर्षति। एष एव प्रतिहतगतिः प्रतिहननहेतुभूतचेतनान् प्रति क्रोधरूपेण परिणतो महापाप्मा परहिंसादिषु प्रवर्तयति एनं रजोगुणसमुद्भवं सहजं ज्ञानयोगविरोधिनं वैरिणं विद्धि।'),
('ramanuja-sc:source:3.38','Rāmānuja','gita.3.38','sa','commentary','।।3.38।।यथा धूमेन वह्निः आव्रियते यथा च आदर्शो मलेन यथा च उल्बेन आवृतो गर्भः तथा तेन कामेन इदं जन्तुजातम् आवृतम्।आवरणप्रकारम् आह'),
('ramanuja-sc:source:3.39','Rāmānuja','gita.3.39','sa','commentary','।।3.39।।अस्य जन्तोः ज्ञानिनो ज्ञानस्वभावस्य आत्मविषयं ज्ञानम् एतेन कामकारेण विषयव्यामोहजननेन नित्यवैरिणा आवृतं दुष्पूरेण पूर्त्यनर्हविषयेण अनलेन च पर्याप्तिरहितेन।कैः उपकरणैः अयं काम आत्मानम् अधितिष्ठति इति अत्र आह'),
('ramanuja-sc:source:3.40','Rāmānuja','gita.3.40','sa','commentary','।।3.40।।अधितिष्ठति एभिः अयं कामः आत्मानम् इति इन्द्रियाणि मनो बुद्धिः अस्य अधिष्ठानम्। एतैः इन्द्रियमनोबुद्धिभिः कामाधिष्ठानभूतैः विषयप्रवणैः देहिनं प्रकृतिसंसृष्टं ज्ञानम् आवृत्य विमोहयति विविधं मोहयति आत्मज्ञानविमुखं विषयानुभवपरं करोति इत्यर्थः।'),
('ramanuja-sc:source:3.41','Rāmānuja','gita.3.41','sa','commentary','।।3.41।।यस्मात् सर्वेन्द्रियव्यापारोपरतिरूपे ज्ञानयोगे प्रवृत्तस्य अयं कामरूपः शत्रुः विषयाभिमुख्यकरणेन आत्मनि वैमुख्यं करोति तस्मात् प्रकृतिसंसृष्टतया इन्द्रियव्यापारप्रवृणः त्वम् आदौ मोक्षोपायारम्भसमये एव इन्द्रियव्यापाररूपे कर्मयोगे इन्द्रियाणि नियम्य एनं ज्ञानविज्ञाननाशनम् आत्मस्वरूपविषयस्य ज्ञानस्य तद्विवेकविषयस्य च नाशनं पाप्मानं कामरूपं वैरिणं प्रजहि नाशय।ज्ञानविरोधिषु प्रधानम् आह'),
('ramanuja-sc:source:3.42','Rāmānuja','gita.3.42','sa','commentary','।।3.42।।ज्ञानविरोधे प्रधानानि इन्द्रियाणि आहुः यत इन्द्रियेषु विषयव्यापृतेषु आत्मनि ज्ञानं न प्रवर्तते इन्द्रियेभ्यः परं मनः इन्द्रियेषु उपरतेषु अपि मनसि विषयप्रवणे आत्मज्ञानं न संभवति। मनसः तु परा बुद्धिः मनसि विषयान्तरविमुखे अपि विपरीताध्यवसायप्रवृत्तायां बुद्धौ न आत्मज्ञानं प्रवर्तते। सर्वेषु बुद्धिपर्यन्तेषु उपरतेषु अपि इच्छापर्यायः कामो रजःसमुद्भवो वर्तते चेत् स एव एतानि इन्द्रियादीनि अपि स्वविषयेषु वर्तयित्वा आत्मज्ञानं निरुणद्धि तदिदम् उच्यते यो बुद्धेः परतः तु सः इति बुद्धेः अपि यः परः स काम इत्यर्थः।'),
('ramanuja-sc:source:3.43','Rāmānuja','gita.3.43','sa','commentary','।।3.43।।एवं बुद्धेः अपि परं कामं ज्ञानविरोधिनं वैरिणं बुद्ध्वा आत्मानं मनः आत्मना बुद्ध्या कर्मयोगे अवस्थाप्य एनं कामरूपं दुरासदं शत्रुं जहि नाशय इति।');
