INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('abhinavagupta-sc:source:2.29','Abhinavagupta','gita.2.29','sa','commentary','।।2.29।।अपि च अव्यक्तादीनीति। नित्यः सन्तु अनित्या वा यस्तावदस्य शोचकस्तं प्रत्येष आदावव्यक्तः अन्ते चाव्यक्तः। मध्ये तस्य व्यक्तता विकारः ( N omit विकारः) इति। प्रत्युत विकारे शोचनीयं ( N शोचनीयस्वभावे) न स्वभावे। किं च यत् (N omits यत्) तन्मूलकारणं किञ्चिदभिमतं तदेव यथाक्रमं (S तथाक्रमविचित्र) विचित्रस्वभावतया स्वात्ममध्ये दर्शिततत्तदनन्तसृष्टिस्थितिसंहृतिवैचित्र्यं (S सृष्टिप्रतिसंहृति) नित्यमेव। तथास्वभावेऽपि कास्य (S स्वभावमिति कास्य) शोच्यता।'),
('abhinavagupta-sc:source:2.30','Abhinavagupta','gita.2.30','sa','commentary','।।2.30।।एवंविधं च आश्चर्यवदिति। ननु यद्येवमयमात्मा अविनाशी किमिति सर्वेण तथैव नोपलभ्यते यतः अद्भुतवत्कश्चिदेव पश्यति श्रुत्वापि एनं (N omit एनम्) न कश्चित् (S N न कश्चिदेव जा ( N कश्चिज्जा) नाति न वेत्ति) वेत्ति न (K omits न) जानाति।'),
('abhinavagupta-sc:source:2.31','Abhinavagupta','gita.2.31','sa','commentary','।।2.31।।देहीति। अतो नित्यमात्मनोऽविनाशित्वम्।'),
('abhinavagupta-sc:source:2.32','Abhinavagupta','gita.2.32','sa','commentary','।।2.32।।स्वधर्ममिति। स्वधर्मस्य च अनपहार्यत्वात् (S N अपरिहार्यत्त्वात्) युद्धविषयः कम्पो न युक्तः।'),
('abhinavagupta-sc:source:2.33','Abhinavagupta','gita.2.33','sa','commentary','।।2.33।।यदृच्छयेति। अन्येऽपि ये (N omits ये) काममयाः क्षत्रियाः तैरपीदृशं युद्धं स्वर्गहेतुत्वात् न त्याज्यम्। किं पुनर्यस्य ईदृशं ज्ञानमुपदिष्टम् इति तात्पर्यम्। न पुनः स्वर्गपर्यवसायी श्लोकः ( N omit न पुनः श्लोकः)।'),
('abhinavagupta-sc:source:2.34','Abhinavagupta','gita.2.34','sa','commentary','।।2.34 2.38।।यद्भयाच्च भवान् युद्धात् निवर्तते (K निवर्तेत) तदेव शतशाखमुपनिपतिष्यति भवत इत्याह अथ चेत्यादि। श्लोकपञ्चकमिदम् अभ्युपगम्यवादरूपमुच्यते ( N उपगम्य) यदि लौकिकेन व्यवहारेणास्ते भवान् तथाप्यवश्यानुष्ठेयमेतत्।'),
('abhinavagupta-sc:source:2.35','Abhinavagupta','gita.2.35','sa','commentary','।।2.34 2.38।।यद्भयाच्च भवान् युद्धात् निवर्तते (K निवर्तेत) तदेव शतशाखमुपनिपतिष्यति भवत इत्याह अथ चेत्यादि। श्लोकपञ्चकमिदम् अभ्युपगम्यवादरूपमुच्यते ( N उपगम्य) यदि लौकिकेन व्यवहारेणास्ते भवान् तथाप्यवश्यानुष्ठेयमेतत्।'),
('abhinavagupta-sc:source:2.36','Abhinavagupta','gita.2.36','sa','commentary','।।2.34 2.38।।यद्भयाच्च भवान् युद्धात् निवर्तते (K निवर्तेत) तदेव शतशाखमुपनिपतिष्यति भवत इत्याह अथ चेत्यादि। श्लोकपञ्चकमिदम् अभ्युपगम्यवादरूपमुच्यते ( N उपगम्य) यदि लौकिकेन व्यवहारेणास्ते भवान् तथाप्यवश्यानुष्ठेयमेतत्।'),
('abhinavagupta-sc:source:2.37','Abhinavagupta','gita.2.37','sa','commentary','।।2.34 2.38।।यद्भयाच्च भवान् युद्धात् निवर्तते (K निवर्तेत) तदेव शतशाखमुपनिपतिष्यति भवत इत्याह अथ चेत्यादि। श्लोकपञ्चकमिदम् अभ्युपगम्यवादरूपमुच्यते ( N उपगम्य) यदि लौकिकेन व्यवहारेणास्ते भवान् तथाप्यवश्यानुष्ठेयमेतत्।'),
('abhinavagupta-sc:source:2.38','Abhinavagupta','gita.2.38','sa','commentary','।।2.34 2.38।।यद्भयाच्च भवान् युद्धात् निवर्तते (K निवर्तेत) तदेव शतशाखमुपनिपतिष्यति भवत इत्याह अथ चेत्यादि। श्लोकपञ्चकमिदम् अभ्युपगम्यवादरूपमुच्यते ( N उपगम्य) यदि लौकिकेन व्यवहारेणास्ते भवान् तथाप्यवश्यानुष्ठेयमेतत्।'),
('abhinavagupta-sc:source:2.39','Abhinavagupta','gita.2.39','sa','commentary','।।2.39।।सुखदुःखे इति। तव तु स्वधर्मतयैव कर्माणि कुर्वतो न कदाचित् पापसंबन्धः।'),
('abhinavagupta-sc:source:2.40','Abhinavagupta','gita.2.40','sa','commentary','।।2.40।।एषा त इति। एषा च तव सांख्ये सम्यग्ज्ञाने बुद्धिर्निश्चयात्मिका उक्ता। एषैव च यथा योगे कर्मकौशलाय उच्यते (S K कौशले यो (S य) ज्यते) तथैव श्रृणु यया बुद्ध्या कर्मणां बन्धकत्वं त्यक्ष्यसि। न हि कर्माणि स्वयं बध्नन्ति जडत्वात्। अतः स्वयमात्मा कर्मभिः वासनात्मकैरात्मानं बध्नाति।'),
('abhinavagupta-sc:source:2.41','Abhinavagupta','gita.2.41','sa','commentary','।।2.41।।नेहेति। इह (S K omit इह) अस्यां बुद्धौ अतिक्रमेण अपराधेन प्रमादेन नाशो न भवति प्रमादस्याभावात्। यथा च (S N तथा च) परिमितेन श्रीखण्डकणेन ज्वालायमानोऽपि तैलकटाहः सद्यः शीतीभवति (N शीतो भवति) एवं अनया स्वल्पयापि (S omits अपि) योगबुद्ध्या महाभयं संसाररूपं विनश्यति।'),
('abhinavagupta-sc:source:2.42','Abhinavagupta','gita.2.42','sa','commentary','।।2.42।।न चैषा बुद्धिरपूर्वानीयते। किं तर्हिव्यवसायात्मिकेति। व्यवसायात्मिका सर्वस्यैकैव (S सर्वस्यैव) सहजा (N omits सहजा) धीः निश्चेतव्यवशात् तु बहुत्वं गच्छति।'),
('abhinavagupta-sc:source:2.43','Abhinavagupta','gita.2.43','sa','commentary','।।2.43 2.45।।तथाच यामिमामित्यादि। ये कामाभिलाषिणः ते स्वयमेतां वाचं वेदात्मिकां पुष्पितां भविष्यत्स्वर्गफलेन ( N omit भविष्यत् S reads भविष्यता) व्याप्तां वदन्ति। अत एव जन्मनः कर्मैव फलमिच्छन्ति ते अविपश्चितः। ते च तयैव स्वयं कल्पितया वेदवाचा अपहृतचित्ताः व्यवसायबुद्धियुक्ता अपि न समाधियोग्याः तत्र फलनिश्चयत्वात्। इति श्लोकत्रयस्य तात्पर्यम्।'),
('abhinavagupta-sc:source:2.44','Abhinavagupta','gita.2.44','sa','commentary','।।2.43 2.45।।तथाच यामिमामित्यादि। ये कामाभिलाषिणः ते स्वयमेतां वाचं वेदात्मिकां पुष्पितां भविष्यत्स्वर्गफलेन ( N omit भविष्यत् S reads भविष्यता) व्याप्तां वदन्ति। अत एव जन्मनः कर्मैव फलमिच्छन्ति ते अविपश्चितः। ते च तयैव स्वयं कल्पितया वेदवाचा अपहृतचित्ताः व्यवसायबुद्धियुक्ता अपि न समाधियोग्याः तत्र फलनिश्चयत्वात्। इति श्लोकत्रयस्य तात्पर्यम्।'),
('abhinavagupta-sc:source:2.45','Abhinavagupta','gita.2.45','sa','commentary','।।2.43 2.45।।तथाच यामिमामित्यादि। ये कामाभिलाषिणः ते स्वयमेतां वाचं वेदात्मिकां पुष्पितां भविष्यत्स्वर्गफलेन ( N omit भविष्यत् S reads भविष्यता) व्याप्तां वदन्ति। अत एव जन्मनः कर्मैव फलमिच्छन्ति ते अविपश्चितः। ते च तयैव स्वयं कल्पितया वेदवाचा अपहृतचित्ताः व्यवसायबुद्धियुक्ता अपि न समाधियोग्याः तत्र फलनिश्चयत्वात्। इति श्लोकत्रयस्य तात्पर्यम्।'),
('abhinavagupta-sc:source:2.46','Abhinavagupta','gita.2.46','sa','commentary','।।2.46।।अत एव च त्रैगुण्येति। वेदास्त्रैगुण्येन करणेन ( N कारणेन) विशेषेण सिन्वन्ति बध्नन्ति (N बध्नन्तीति) न ( N omit न तु) तु स्वयं बन्धका यस्मात् सुखदुःखमोहबुद्ध्या कर्माणि वैदिकानि क्रियमाणानि बन्धकानि अतः त्रैगुण्यं कामरूपं त्याज्यम्। यदि तु वेददूषणपरमेतदभविष्यत् प्रकृतं युद्धकरणं व्यघटिष्यत वेदादन्यस्य स्वधर्मनिश्चायकत्वाभावात्। येषां तु फलाभिलाषो विगलितः तेषां न वेदाः बन्धकाः।'),
('abhinavagupta-sc:source:2.47','Abhinavagupta','gita.2.47','sa','commentary','।।2.47।।यतो वेदाः परं तेषां सम्यग्ज्ञानोपयोगिनः अत एवाह (K omits एव) यावानिति। यस्य स्वधर्ममात्रे (N omits स्व ) ज्ञाने वा प्राधान्यं तस्य परिमितादपि वेदभाषितात् कार्यं सम्पद्यते ।'),
('abhinavagupta-sc:source:2.48','Abhinavagupta','gita.2.48','sa','commentary','।।2.48।।अतश्च कर्मणीति। कर्ममात्रे त्वं व्यापृतो भव न तु कर्मफलेषु। ननु कर्मणि कृते ( omits कृते N substitutes जाते) नान्तरीयकतयैव फलमापततीति मैवम्। तत्र हि यदि त्वं फलकामनाकालुष्यव्याप्तो भवसि तदा कर्मणां फलं प्रति हेतुत्वम्। यत् अप्रार्थ्यमानं फलं तत् (S N omit तत्) ज्ञानं नानिच्छोस्तत् इति। कर्माभावेन यः संगः स एव गाढग्रहरूपो मिथ्याज्ञानस्वरूपः इति त्याज्य एव ( N इत्यत्याज्य एव)।'),
('abhinavagupta-sc:source:2.49','Abhinavagupta','gita.2.49','sa','commentary','।।2.49।।किं तर्हि योगस्थ इति। योगे स्थित्वा कर्माणि कुरु। साम्यं च योगः।'),
('abhinavagupta-sc:source:2.50','Abhinavagupta','gita.2.50','sa','commentary','।।2.50।।No commentary.'),
('abhinavagupta-sc:source:2.51','Abhinavagupta','gita.2.51','sa','commentary','।।2.51।।दूरेण हीति। बुद्धियोगात्किल हेतोः अवरं दुष्टफलयुक्तं (K omits युक्तं) रिक्तं ( omits रिक्तं) कर्म दूरीभवति। अतस्तादृश्यां बुद्धौ शरणमन्विच्छ प्रार्थयस्व येन सा बुद्धिः लभ्यते।'),
('abhinavagupta-sc:source:2.52','Abhinavagupta','gita.2.52','sa','commentary','।।2.52।।बुद्धियुक्त इति। उभे इति परस्परव्यभिचारं दर्शयति। तस्माद्योगायेति। यथा हि सुकृतदुष्कृते नश्यतः (N दुष्कृते न नश्यतः) तथाकरणमेव परमं कौशलमिति भावः।'),
('abhinavagupta-sc:source:2.53','Abhinavagupta','gita.2.53','sa','commentary','।।2.53।।कर्मजमिति। योगबुद्धियुक्ताः कर्मणां फलं त्यक्त्वा जन्मबन्धं त्यजन्ति ब्रह्मसत्तामाप्नुवन्ति (S K अवाप्नुवन्ति)।'),
('abhinavagupta-sc:source:2.54','Abhinavagupta','gita.2.54','sa','commentary','।।2.54 2.55।।यदा ते इति। श्रुतीति। तत्र च योगबुद्धिप्राप्त्यबसरे तव स्फुटमेवेदमभिज्ञानम् श्रोतव्यस्य (S omits श्रोतव्यस्य) श्रुतस्य अभिलष्यमाणस्य च (N वा instead of च) आगमस्य उभस्यापि निर्वेदभावत्वम् (SK भाक्त्वम्)। अनेन चेदमुक्तम् अविद्यापद ( N अविद्यमद) निपतितप्रमात्रनुग्राहकशास्त्रश्रवणसंस्कारविप्रलम्भमहिमा अयं यत् तवास्थाने कुलक्षयादिदोषदर्शनम्। तत्तु तथाशासनबहुमानविगलने विगलिष्यति इति।'),
('abhinavagupta-sc:source:2.55','Abhinavagupta','gita.2.55','sa','commentary','।।2.54 2.55।।यदा ते इति। श्रुतीति। तत्र च योगबुद्धिप्राप्त्यबसरे तव स्फुटमेवेदमभिज्ञानम् श्रोतव्यस्य (S omits श्रोतव्यस्य) श्रुतस्य अभिलष्यमाणस्य च (N वा instead of च) आगमस्य उभस्यापि निर्वेदभावत्वम् (SK भाक्त्वम्)। अनेन चेदमुक्तम् अविद्यापद ( N अविद्यमद) निपतितप्रमात्रनुग्राहकशास्त्रश्रवणसंस्कारविप्रलम्भमहिमा अयं यत् तवास्थाने कुलक्षयादिदोषदर्शनम्। तत्तु तथाशासनबहुमानविगलने विगलिष्यति इति।'),
('abhinavagupta-sc:source:2.56','Abhinavagupta','gita.2.56','sa','commentary','।।2.56।।स्थितप्रज्ञस्येति। यदा स्थास्यति बुद्धिः इत्यनेन वचसा समाधिस्थस्य योगिनो यः स्थितप्रज्ञशब्दः (स्थित and स्थिर are found often interchanged in CA.) ( N omit शब्दः) तत्र वाचक उक्तस्तस्य का भाषा किं प्रवृत्तिनिमित्तम् भाष्यते येन निमित्तेन शब्दैरर्थ इति कृत्वा। योगिनः स्थितप्रज्ञशब्दः ( N omit शब्दः) किं रूढ्या वाचकः अन्वर्थतया वा (S omits वा) इत्येकः प्रश्नः। यद्यपि रूढौ शङ्कैव नास्ति तथापि अन्वर्थतां लब्धामपि स्वरूपलक्षणनिमित्तानिरूपणेन ( N त्तरूपेण) स्फुटीकर्तुमेष (S प्रस्फुटी) प्रश्नः। स्थिरधीरिति शब्दपदार्थकः अर्थपदार्थकश्च। तत्र ( N omit च तत्र) स्थिरधीशब्दः किं प्रयोगलक्षणमेवार्थमाह आहो तपस्विनमपि इति द्वितीयः प्रश्नः। स च स्थिरधीर्योगी किमासीत किमभ्यसेत् क्वास्य स्थैर्यं स्यात् इति तृतीयः। अभ्यस्यंश्च (N अभ्यसंश्च) किमाप्नुयात् इति चतुर्थः। एतदेव प्रश्नचतुष्टयं क्रमेण निर्णीयते भगवता (S इति प्रश्नचतुष्यम् अज्ञा (र्जु) नेन कृतं क्रमेण निर्णीयते श्रीभगवता)।'),
('abhinavagupta-sc:source:2.57','Abhinavagupta','gita.2.57','sa','commentary','।।2.57।।प्रजहातीति। स्थिता रूढा प्रज्ञा यस्य। रूढिश्च नित्यमात्मरूढित्वे सति विषयविक्षेपकृतस्य कामरूपस्य (N omits कामरूपस्य) भ्रमस्य निवृत्तत्वात् योगिनो यः स्थितप्रज्ञशब्दः अन्वर्थः स च इत्थं (N omits इत्थं) युक्तः इत्येकः प्रश्नो निर्णीतः।'),
('abhinavagupta-sc:source:2.58','Abhinavagupta','gita.2.58','sa','commentary','।।2.58।।दुःखेष्विति। सुखदुःखयोर्यस्य रागद्वेषरहिता (S विरहिता) वृत्तिः स मुनिरेव स्थितप्रज्ञः नान्यः।'),
('abhinavagupta-sc:source:2.59','Abhinavagupta','gita.2.59','sa','commentary','।।2.59।।युक्तं चैतत् यतः यः सर्वत्रेति। शुभाशुभप्राप्तौ तस्याह्लादतापौ न भवतः।'),
('abhinavagupta-sc:source:2.60','Abhinavagupta','gita.2.60','sa','commentary','।।2.60।।यदा संहरते इति। न चास्य पाचकवद्योगरूढत्वम्। यदा यदा किलायमिन्द्रियाणि संहरते आत्मन्येव कूर्म इवाङ्गानि क्रोडीकरोति विषयेभ्यः विषयान्निवार्य (S विषयेभ्यः विषयार्थस्यैव विषयान्निवार्य) तदा तदा स्थिरप्रज्ञः। यद्वा इन्द्रियार्थेभ्यः प्रभृति इन्द्रियाणि आत्मनि संहरते विषयेन्द्रियात्मकं (K न्द्रियादिकम्) सर्वम् ( N आसन्नं instead सर्वम्) आत्मसात्कुरुते।'),
('abhinavagupta-sc:source:2.61','Abhinavagupta','gita.2.61','sa','commentary','।।2.61।।ननु तपस्विनोऽपि कथं स्थितप्रज्ञशब्दो न प्रवर्तते उच्यते विषया इति। यद्यपि आह्ार्यैः रूपादिभिर्विषयैः संबन्धोऽस्य नास्ति तथापि तस्य विषया अन्तःकरणगतमुपरागलक्षणं रसं वर्जयित्वा एव निवर्तन्ते। अतो नासौ स्थिरप्रज्ञः। रसं केचिदास्वाद्यं मधुरादिकमाहुः (K omits this entire sentence )। योगिनस्तु परमेश्वरदर्शनात् उपरागो न (N omits न) भवति। अन्यस्य तु तपस्विनो नासौ निवर्तते।'),
('abhinavagupta-sc:source:2.62','Abhinavagupta','gita.2.62','sa','commentary','।।2.62।।यत्तस्यापीति। यत् यस्मात् तस्यापि तपस्विनो मन इन्द्रियैः ह्रियते। अथवा यत्तस्य सयत्नस्यापि। योगिना च मन एव जेतव्यमिति द्वितीयो निर्णीतः।'),
('abhinavagupta-sc:source:2.63','Abhinavagupta','gita.2.63','sa','commentary','।।2.63।।तानीति। य एवं मनसा इन्द्रियाणि नियमयति न त्वप्रवृत्त्या स एव स्थिरप्रज्ञः। स च मत्पर आसीत मामेव चिदात्मानं परमेश्वरमभ्यस्येत् ( N अभ्यसेत्)।'),
('abhinavagupta-sc:source:2.64','Abhinavagupta','gita.2.64','sa','commentary','।।2.64 2.65।।ध्यायत इति। क्रोधादिति। तपस्विनो विषयत्याग एव विषयग्रहणे पर्यवस्यति। ध्यात्वा हि ते त्यजन्ते। ध्यानकाले एव च (S omits च) संगादयः उपजायन्ते इति अनपायो (K अनुपायो) विषयत्यागः स्थिरप्रज्ञस्य एव ।'),
('abhinavagupta-sc:source:2.65','Abhinavagupta','gita.2.65','sa','commentary','।।2.64 2.65।।ध्यायत इति। क्रोधादिति। तपस्विनो विषयत्याग एव विषयग्रहणे पर्यवस्यति। ध्यात्वा हि ते त्यजन्ते। ध्यानकाले एव च (S omits च) संगादयः उपजायन्ते इति अनपायो (K अनुपायो) विषयत्यागः स्थिरप्रज्ञस्य एव ।'),
('abhinavagupta-sc:source:2.66','Abhinavagupta','gita.2.66','sa','commentary','।।2.66 2.70।।रागद्वेषेत्यादि प्रतिष्ठितेत्यन्तम्। यस्तु मनसो नियामकः स विषयान् सेवमानोऽपि न क्रोधादिकल्लोलैरभिभूयते इति स एव स्थितप्रज्ञो योगीति तात्पर्यम्।'),
('abhinavagupta-sc:source:2.67','Abhinavagupta','gita.2.67','sa','commentary','।।2.66 2.70।।रागद्वेषेत्यादि प्रतिष्ठितेत्यन्तम्। यस्तु मनसो नियामकः स विषयान् सेवमानोऽपि न क्रोधादिकल्लोलैरभिभूयते इति स एव स्थितप्रज्ञो योगीति तात्पर्यम्।'),
('abhinavagupta-sc:source:2.68','Abhinavagupta','gita.2.68','sa','commentary','।।2.66 2.70।।रागद्वेषेत्यादि प्रतिष्ठितेत्यन्तम्। यस्तु मनसो नियामकः स विषयान् सेवमानोऽपि न क्रोधादिकल्लोलैरभिभूयते इति स एव स्थितप्रज्ञो योगीति तात्पर्यम्।'),
('abhinavagupta-sc:source:2.69','Abhinavagupta','gita.2.69','sa','commentary','।।2.66 2.70।।रागद्वेषेत्यादि प्रतिष्ठितेत्यन्तम्। यस्तु मनसो नियामकः स विषयान् सेवमानोऽपि न क्रोधादिकल्लोलैरभिभूयते इति स एव स्थितप्रज्ञो योगीति तात्पर्यम्।'),
('abhinavagupta-sc:source:2.70','Abhinavagupta','gita.2.70','sa','commentary','।।2.66 2.70।।रागद्वेषेत्यादि प्रतिष्ठितेत्यन्तम्। यस्तु मनसो नियामकः स विषयान् सेवमानोऽपि न क्रोधादिकल्लोलैरभिभूयते इति स एव स्थितप्रज्ञो योगीति तात्पर्यम्।'),
('abhinavagupta-sc:source:2.71','Abhinavagupta','gita.2.71','sa','commentary','।।2.71।।योगी च सर्वव्यवहारान् कुर्वाणोऽपि (S omits अपि) लोकोत्तर इति निरूपयता परमेश्वरेण संक्षिप्यास्य स्वरूपं कथ्यते या निशेति। या सर्वेषां भूतानां निशा मोहिनी (K मोहनी) माया तस्यां मुनिर्जागर्त्ति कथमियं हेया इति। यस्यां च दशायां लोको जगर्त्ति नानाविधां (S विविधां) चेष्टां कुरुते सा मुनेः रात्रिः यतोऽसौ व्यवहारं प्रत्यबुद्धः।एतदुक्तं भवति येयं माया खलु तस्या द्वे रूपे ( N omit द्वे रूपे) मोहकत्वं ( N मोहकत्वे) नाम रूपं सुखतन्त्र ( N तन्तु for तन्त्र hereinafter ) ताभासनं च। तत्र लोकः प्राच्यं स्वरूपमस्या अपरामृश्यैव द्वितीयस्मिन् रूपे निबद्धस्मृतिरास्ते। योगी तु तद्विपरीतस्तदीयं मोहकत्वं तदुन्मूलनाय पश्यति। सुखतन्त्रतां च नाद्रियते (N नाश्रीयते) पश्यन् सम्यग्ज्ञानी। मिथ्याज्ञानोपघाताच्च सुखतन्त्रतानादरः (S तन्त्रतायां नादरः)। एवं च पश्यत एव सा रात्रिरिति चित्रम्। विद्याया वा बुध्यते (S K यां चावधत्ते) योगी यत्र सर्वोऽपि (S N omit अपि) विमूढः अविद्यायां त्वबुद्धः यत्र जनः प्रबुद्ध इत्यपि चित्रम्।'),
('abhinavagupta-sc:source:2.72','Abhinavagupta','gita.2.72','sa','commentary','।।2.72।।अत एव आपूर्यमाणमिति। योगी न कामार्थ बहिर्धावति अपि तु इन्द्रियधर्मतया तं ( N omit तं and read विषयानुप्रविशन्तो नतरां यान्ति ( न तरंगयन्ति) विषया अनुप्रविशन्तो न तरङ्गयन्ति नदीवेगा इवोदधिम्। एवं तृतीयो निर्णीतः।'),
('abhinavagupta-sc:source:3.1','Abhinavagupta','gita.3.1','sa','commentary','।।3.1 3.2।।ज्यायसीति। व्यामिश्रेणेति। कर्म उक्तं ज्ञानं च। तत्र न द्वयोः प्राधान्यं युक्तम् अपि तु ज्ञानस्य। तद्बलेन क्षपणीयत्वं यदि कर्मणां बुद्धियुक्तो जहातीमे (II 52) इत्यादिनयेन मूलत एव तर्हि (K तत्) कर्मणां (S K कर्मणा) किं प्रयोजनमिति प्रश्नाभिप्रायः।'),
('abhinavagupta-sc:source:3.2','Abhinavagupta','gita.3.2','sa','commentary','।।3.1 3.2।।ज्यायसीति। व्यामिश्रेणेति। कर्म उक्तं ज्ञानं च। तत्र न द्वयोः प्राधान्यं युक्तम् अपि तु ज्ञानस्य। तद्बलेन क्षपणीयत्वं यदि कर्मणां बुद्धियुक्तो जहातीमे (II 52) इत्यादिनयेन मूलत एव तर्हि (K तत्) कर्मणां (S K कर्मणा) किं प्रयोजनमिति प्रश्नाभिप्रायः।'),
('abhinavagupta-sc:source:3.3','Abhinavagupta','gita.3.3','sa','commentary','।।3.3।।श्रीभगवांस्तूत्तरं ददाति लोकेऽस्मिन् इति। लोके एषा द्वयी गतिः प्रसिद्धा सांख्यानां ज्ञानं प्रधानम् योगिनां च कर्मेति। मया तु सा एकैव निष्ठा उक्ता ज्ञानक्रियामयत्वात् संवित्तत्त्वस्येति भावः।'),
('abhinavagupta-sc:source:3.4','Abhinavagupta','gita.3.4','sa','commentary','।।3.4 3.5।।तथा हि न कर्मणामिति। न हीति। ज्ञानं कर्मणा रहितं न भवति कर्म च कौशलोपेतं ज्ञानरहितं न भवति इत्येकमेव वस्तु ज्ञानकर्मणी। तथाचोक्तम्।न क्रियारहितं ज्ञानं न ज्ञानरहिता क्रिया।ज्ञानक्रियाविनिष्पन्न आचार्यः पशुपाशहा।। इति तस्मात् ज्ञानान्तर्वर्ति कर्म अपरिहार्यम्। यतः परवश एव कायवाङ्मनसां परिस्पन्दात्मकत्वात् अवश्यं किञ्चित्करोति।'),
('abhinavagupta-sc:source:3.5','Abhinavagupta','gita.3.5','sa','commentary','।।3.4 3.5।।तथा हि न कर्मणामिति। न हीति। ज्ञानं कर्मणा रहितं न भवति कर्म च कौशलोपेतं ज्ञानरहितं न भवति इत्येकमेव वस्तु ज्ञानकर्मणी। तथाचोक्तम्।न क्रियारहितं ज्ञानं न ज्ञानरहिता क्रिया।ज्ञानक्रियाविनिष्पन्न आचार्यः पशुपाशहा।। इति तस्मात् ज्ञानान्तर्वर्ति कर्म अपरिहार्यम्। यतः परवश एव कायवाङ्मनसां परिस्पन्दात्मकत्वात् अवश्यं किञ्चित्करोति।'),
('abhinavagupta-sc:source:3.6','Abhinavagupta','gita.3.6','sa','commentary','।।3.6।।कर्मेन्द्रियाणीति। कर्मेन्द्रियैश्चेन्न करोति अवश्यं तर्हि (S omits तर्हि) मनसा करोति प्रत्युत सः मूढाचारः (The expressions मूढाचारः and मिथ्याचारः are found hereinafter interchanged in the MSS. ) मानसानां कर्मणामत्यन्तमपरिहार्यत्वात्।'),
('abhinavagupta-sc:source:3.7','Abhinavagupta','gita.3.7','sa','commentary','।।3.7।।यस्त्विति। कर्मसु क्रियामणेषु न ज्ञानहानिः। मनसोऽव्यापारे यन्त्रपुरुषवत् कर्मणः क्रियमाणत्वात्।'),
('abhinavagupta-sc:source:3.8','Abhinavagupta','gita.3.8','sa','commentary','।।3.8।।अतः नियतमिति। नियतं शास्त्रीयं कर्म कुरु। शरीरयात्रामात्रस्यापि कर्माधीनत्वात्।'),
('abhinavagupta-sc:source:3.9','Abhinavagupta','gita.3.9','sa','commentary','।।3.9।।यतः यज्ञार्थात् इति। यज्ञार्थात् अवश्यकरणीयात् अन्यानि कर्माणि बन्धकानि। अवश्यकर्तव्यं ( omits अवश्यकर्तव्यम्) मुक्तफलसंगतया क्रियमाणं न फलदम्।'),
('abhinavagupta-sc:source:3.10','Abhinavagupta','gita.3.10','sa','commentary','।।3.10।।सहेति। प्रजापतिः परमात्मा प्रजाः सहैव कर्मभिः ससर्ज। उक्तं च (N omits उक्तं च) तेन प्रजानां कर्मभ्य एव प्रसवः सन्तानः। एतान्येव च इष्टं संसारं मोक्षं वा दास्यन्ति संगात्संसारं मुक्तसंगत्वान्मोक्षम् इति ।'),
('abhinavagupta-sc:source:3.11','Abhinavagupta','gita.3.11','sa','commentary','।।3.11।।य(त)त्र येषां मोक्षप्राधान्यं तैरेव विषयाः सेव्या इत्युच्यते देवानिति। देवाः क्रीडाशीलाः (K क्रीडनशीलाः) इन्द्रियवृत्तयः करणेश्वर्यो देवता रहस्यशास्त्रप्रसिद्धाः ताः अनेन कर्मणा तर्पयत ययासंभवं विषयान् भक्षयतेत्यर्थः। तृप्ताश्च सत्यस्ता वो (S सत्यो वो) युष्मान् आत्मन एव स्वरूपमात्रोचितान् अपवर्गान् (S चितापवर्गान्) भावयन्तु स्वात्मस्थितियोगत्वात्। एवमनवरतं व्युत्थानसमाधिसमयपरम्परायाम् (S रतव्युत्थान ) इन्द्रियतर्पणदात्मासाद्भावलक्षणे ( सद्भाव ) परस्परभावने सति शीघ्रमेव परमं श्रेयः परस्परभेदविगलनलक्षणं ब्रह्म प्राप्स्यथ।'),
('abhinavagupta-sc:source:3.12','Abhinavagupta','gita.3.12','sa','commentary','।।3.12।।न केवलमित्थमपवर्गे यावत्सिद्धिलाभेऽपि अयं मार्गः अभ्यसनीय इत्याह इष्टानिति। यज्ञतर्पितानि हि इन्द्रियाणि स्थितिं बध्नन्ति यत्रक्वापि ध्येयादौ इति। अत एव तद्व्यापारे सति तेषां विषयाणां स्मृतिसंकल्पध्यानादिना भावाः विषयाः इन्द्रियैरेव दत्ताः। यदि तेषामेवोपभोगाय विषया (S K omit विषयाः) न दीयन्ते तर्हि स्तेनत्वं चौर्यं स्यात् छद्मचारित्वात्। उक्तं हि पूर्वमेव भगवता मूढाचारः स उच्यते (II 6 ) इति। अतो़ऽयं वाक्यार्थः यः सुखोपायं सिद्धिम् अपवर्गं वा प्रेप्सति तेन इन्द्रियकौतुकनिवृत्तिमात्रफलतयैव भोगा यथोपनतमासेव्या इति।'),
('abhinavagupta-sc:source:3.13','Abhinavagupta','gita.3.13','sa','commentary','।।3.13।।यज्ञशिष्टेति। अवश्यकर्तव्यतारूपशासनमहिमायातान् भोगान् येऽश्नन्ति अवान्तरव्यापारमात्रतया अत एव च पृथक्फलत्वाभावाङ्गतया अथ च इन्द्रियात्मकदेवगणतर्पणलक्षणयज्ञादवशिष्टम् अन्तःसारस्वात्मस्थित्यानन्दलक्षणविघसं येऽश्नन्ति तत्रारूढा ( तत्रामूढाः) भवन्ति तदुपादेयोपायतया(S तत्रोपादे ) तु विषयभोगं वाञ्छन्ति ते सर्वाकल्बिषैः शुभाशुभैः मुच्यन्ते। ये त्वात्मकारणादिति अविद्यावशात् स्थूलमेव विषयभोगं परत्वेन (S भोगपरत्वेन) मन्वानाः आत्मार्थमिदं वयं कुर्म इति कुर्वते त एवाघं शुभाशुभात्मकं लभन्ते।'),
('abhinavagupta-sc:source:3.14','Abhinavagupta','gita.3.14','sa','commentary','।।3.14 3.15।।अन्नादिति। कर्मेति। अन्नात् अविभागभोग्यस्वभावात् कथंचित् मायाविद्याकालाद्यनेकापरपर्यायात् (S N विद्याप्रकृतिकाला ) भूतानि विचित्राणि भवन्ति। तच्च अन्नं पर्जन्यात् अविच्छिन्नसंवित्स्वभावात् आत्मनः भोक्तृतन्त्रात्मलाभत्वात् भोग्यतायाः। स च पर्जन्यो भोक्ता यज्ञात् भोगक्रियात्मनः भोगक्रियायत्तत्वात् भोक्तृत्वस्य। भोगक्रिया च कर्मणः क्रियाशक्तिस्वातन्त्र्यबलात्। तच्च स्वातन्त्र्यम् अविच्छिन्नमपि (S अविच्छन्नमपि अविच्छन्नस्यापि अनवच्छिन्नानन्त ) अनवच्छिन्नानन्तस्वातन्त्र्यपूर्णसमुच्चलन्महेश्वरभावपरमात्मब्रह्मणः संस्पर्शवशात् (S K ब्रह्मसंस्पर्श )। तच्च ( omits तच्च) उच्चलदच्छानाछादितैश्वर्यं ( N इच्छादितैश्वर्यम्) ब्रह्म अक्षरात् प्रशान्ताशेषैश्वर्यतरङ्गात् संविन्मात्रात्। इत्येवं सुव्यवस्थितो (S स्थितोऽयम् भोगक्रियायाम्) यज्ञः षडरं चक्रं वाहयन् तत्र (K omits तत्र S N substitute तत्तु) अरात्रयसंधानादपवर्गम् अरात्रयतन्त्रणात् व्यवहारमासूत्रयति इति विद्याविद्योल्लासतरंगसुभगं ब्रह्म ( तरङ्गं ब्रह्म) यज्ञे एव प्रतिष्ठितम्।अन्ये तु अन्नं तावद्वीर्यलोहितक्रमेण भूतकारणम् अन्नं च वृष्टिद्वारेण पर्जन्यात् सोऽपि अग्नौ प्रास्ताहुतिः सम्यक् (S omits सम्यक् K omits the entire quotation ) इति आदित्यमेति। ततो वृष्टिर्यज्ञात् यज्ञः क्रियातः सा च ज्ञानपूर्विका ज्ञानमक्षरात् इति।अपरे तु अन्नं अद्यमानं विषयपञ्चकम् तत् आश्रित्य भूतानि इन्द्रियाणि विषयाश्चात्मनः स्फुरितरूपाः। अत आत्मैव विषयोपभोगेन पोष्यते। अतश्च सर्वगतं (S अतः सर्वगम्) ब्रह्म कर्मणि प्रतिष्ठितं तन्मयत्वात् तस्य इति ।'),
('abhinavagupta-sc:source:3.15','Abhinavagupta','gita.3.15','sa','commentary','।।3.14 3.15।।अन्नादिति। कर्मेति। अन्नात् अविभागभोग्यस्वभावात् कथंचित् मायाविद्याकालाद्यनेकापरपर्यायात् (S N विद्याप्रकृतिकाला ) भूतानि विचित्राणि भवन्ति। तच्च अन्नं पर्जन्यात् अविच्छिन्नसंवित्स्वभावात् आत्मनः भोक्तृतन्त्रात्मलाभत्वात् भोग्यतायाः। स च पर्जन्यो भोक्ता यज्ञात् भोगक्रियात्मनः भोगक्रियायत्तत्वात् भोक्तृत्वस्य। भोगक्रिया च कर्मणः क्रियाशक्तिस्वातन्त्र्यबलात्। तच्च स्वातन्त्र्यम् अविच्छिन्नमपि (S अविच्छन्नमपि अविच्छन्नस्यापि अनवच्छिन्नानन्त ) अनवच्छिन्नानन्तस्वातन्त्र्यपूर्णसमुच्चलन्महेश्वरभावपरमात्मब्रह्मणः संस्पर्शवशात् (S K ब्रह्मसंस्पर्श )। तच्च ( omits तच्च) उच्चलदच्छानाछादितैश्वर्यं ( N इच्छादितैश्वर्यम्) ब्रह्म अक्षरात् प्रशान्ताशेषैश्वर्यतरङ्गात् संविन्मात्रात्। इत्येवं सुव्यवस्थितो (S स्थितोऽयम् भोगक्रियायाम्) यज्ञः षडरं चक्रं वाहयन् तत्र (K omits तत्र S N substitute तत्तु) अरात्रयसंधानादपवर्गम् अरात्रयतन्त्रणात् व्यवहारमासूत्रयति इति विद्याविद्योल्लासतरंगसुभगं ब्रह्म ( तरङ्गं ब्रह्म) यज्ञे एव प्रतिष्ठितम्।अन्ये तु अन्नं तावद्वीर्यलोहितक्रमेण भूतकारणम् अन्नं च वृष्टिद्वारेण पर्जन्यात् सोऽपि अग्नौ प्रास्ताहुतिः सम्यक् (S omits सम्यक् K omits the entire quotation ) इति आदित्यमेति। ततो वृष्टिर्यज्ञात् यज्ञः क्रियातः सा च ज्ञानपूर्विका ज्ञानमक्षरात् इति।अपरे तु अन्नं अद्यमानं विषयपञ्चकम् तत् आश्रित्य भूतानि इन्द्रियाणि विषयाश्चात्मनः स्फुरितरूपाः। अत आत्मैव विषयोपभोगेन पोष्यते। अतश्च सर्वगतं (S अतः सर्वगम्) ब्रह्म कर्मणि प्रतिष्ठितं तन्मयत्वात् तस्य इति ।'),
('abhinavagupta-sc:source:3.16','Abhinavagupta','gita.3.16','sa','commentary','।।3.16।।एवमिति। यस्तु एवं नाङ्गीकरोति स पापमयः। यतः (N अतः) स इन्द्रियेष्वेव रमते नात्मनि।'),
('abhinavagupta-sc:source:3.17','Abhinavagupta','gita.3.17','sa','commentary','।।3.17 3.19।।यश्चेत्यादि पूरुष इत्यन्तम्। आत्मरतेस्तु कर्म इन्द्रियव्यापारतयैव कुर्वतः करणाकरणेषु समता। अत एव नासौ भूतेषु किंचिदात्मप्रयोजनमपेक्ष्य निग्रहानुग्रहौ करोति अपि तु करणीयमिदम् इत्येतावता। तस्मादसक्त एव करणीयं कर्म कुर्यात्।'),
('abhinavagupta-sc:source:3.18','Abhinavagupta','gita.3.18','sa','commentary','।।3.17 3.19।।यश्चेत्यादि पूरुष इत्यन्तम्। आत्मरतेस्तु कर्म इन्द्रियव्यापारतयैव कुर्वतः करणाकरणेषु समता। अत एव नासौ भूतेषु किंचिदात्मप्रयोजनमपेक्ष्य निग्रहानुग्रहौ करोति अपि तु करणीयमिदम् इत्येतावता। तस्मादसक्त एव करणीयं कर्म कुर्यात्।'),
('abhinavagupta-sc:source:3.19','Abhinavagupta','gita.3.19','sa','commentary','।।3.17 3.19।।यश्चेत्यादि पूरुष इत्यन्तम्। आत्मरतेस्तु कर्म इन्द्रियव्यापारतयैव कुर्वतः करणाकरणेषु समता। अत एव नासौ भूतेषु किंचिदात्मप्रयोजनमपेक्ष्य निग्रहानुग्रहौ करोति अपि तु करणीयमिदम् इत्येतावता। तस्मादसक्त एव करणीयं कर्म कुर्यात्।'),
('abhinavagupta-sc:source:3.20','Abhinavagupta','gita.3.20','sa','commentary','।।3.20।।कर्मणैवेति। तदत्र कर्म कुर्वतामपि सिद्धौ जनकादयो दृष्टान्ताः।'),
('abhinavagupta-sc:source:3.21','Abhinavagupta','gita.3.21','sa','commentary','।।3.21 3.22।।यद्यदाचरतीति। न मे इति। प्राप्तप्रापणीयस्य परिपूर्णमनसोऽपि कर्मप्रवृत्तौ लोकानुग्रहः प्रयोजनमित्यत्र श्रीभगवान् आत्मानमेव दृष्टान्तीकरोति।'),
('abhinavagupta-sc:source:3.22','Abhinavagupta','gita.3.22','sa','commentary','।।3.21 3.22।।यद्यदाचरतीति। न मे इति। प्राप्तप्रापणीयस्य परिपूर्णमनसोऽपि कर्मप्रवृत्तौ लोकानुग्रहः प्रयोजनमित्यत्र श्रीभगवान् आत्मानमेव दृष्टान्तीकरोति।'),
('abhinavagupta-sc:source:3.23','Abhinavagupta','gita.3.23','sa','commentary','।।3.23 3.25।।यदीत्यादि लोकसंग्रहमित्यन्तम्। किं च विदितवेद्यः कर्म चेत् त्यजेत् तत् लोकानां दुर्भेद एव एकप्रसिद्धपक्षशिथिलितास्थाबन्धत्वेनाप्ररूढिलक्षणो जायेत (S K जायते)। यतः (S omits यतः) कर्मवासनां च न मोक्तुं शक्नुवन्ति ज्ञानधारां च नाश्रयितुम् अथ च शिथिलीभवन्ति।'),
('abhinavagupta-sc:source:3.24','Abhinavagupta','gita.3.24','sa','commentary','।।3.23 3.25।।यदीत्यादि लोकसंग्रहमित्यन्तम्। किं च विदितवेद्यः कर्म चेत् त्यजेत् तत् लोकानां दुर्भेद एव एकप्रसिद्धपक्षशिथिलितास्थाबन्धत्वेनाप्ररूढिलक्षणो जायेत (S K जायते)। यतः (S omits यतः) कर्मवासनां च न मोक्तुं शक्नुवन्ति ज्ञानधारां च नाश्रयितुम् अथ च शिथिलीभवन्ति।'),
('abhinavagupta-sc:source:3.25','Abhinavagupta','gita.3.25','sa','commentary','।।3.23 3.25।।यदीत्यादि लोकसंग्रहमित्यन्तम्। किं च विदितवेद्यः कर्म चेत् त्यजेत् तत् लोकानां दुर्भेद एव एकप्रसिद्धपक्षशिथिलितास्थाबन्धत्वेनाप्ररूढिलक्षणो जायेत (S K जायते)। यतः (S omits यतः) कर्मवासनां च न मोक्तुं शक्नुवन्ति ज्ञानधारां च नाश्रयितुम् अथ च शिथिलीभवन्ति।'),
('abhinavagupta-sc:source:3.26','Abhinavagupta','gita.3.26','sa','commentary','।।3.26।।यतस्ते न (S स्ते सम्य ) सम्यग्ज्ञानेन पूताः अतो बुद्धेर्भेदनं विचालनं ( N विगलनम्) तेषां परमोऽयमनर्थ इत्यनुग्रहाय भेदयेन्न धियमेषाम् तदाह (S एतदाह) न बुद्धीति। स्वयं चैवं बुद्ध्यमानः कर्माणि कुर्यात् न च लोकानां बुद्धिं भिन्द्यात्।'),
('abhinavagupta-sc:source:3.27','Abhinavagupta','gita.3.27','sa','commentary','।।3.27।।अज्ञानामित्युक्तम्। तदज्ञत्वं दर्शयति प्रकृतेरिति। प्रकृतिसंबन्धिभिः गुणैः सत्त्वाद्यैः किल कर्माणि क्रियन्ते। मूढश्च अहं कर्ता इत्यध्यवस्य(S omits अध्यवस्य) मिथ्यैव आत्मानं बध्नाति।'),
('abhinavagupta-sc:source:3.28','Abhinavagupta','gita.3.28','sa','commentary','।।3.28।।तत्त्ववित्त्विति। गुणकर्मविभागवित्तु प्रकृतिः करोति मम किमायातम् इत्यात्मानं मोचयति।'),
('abhinavagupta-sc:source:3.29','Abhinavagupta','gita.3.29','sa','commentary','।।3.29।।कर्मसंगिनामित्युक्तम्। तत् ( N omit तत्) कर्मसंगित्वं (S omits कर्मसंगित्वम्) दर्शयति प्रकृतेरिति। प्रकृतिसंबन्धिभिर्गुणैः सत्त्वाद्यैः (S omit सत्त्वाद्यैः) कृतेषु कर्मसु मूढाः सज्जन्ति( मज्जन्ति) सत्त्वादिगुणमाहात्म्यात्।'),
('abhinavagupta-sc:source:3.30','Abhinavagupta','gita.3.30','sa','commentary','।।3.30।।तस्माद्युक्तः सन् जुषेत कर्माणि इत्युक्तं तत्र तत् कथमिति स्फुटयति मयीति। मयि सर्वाणि (S मयि स्थित्वा सर्वाणि) कर्माणि नाहं कर्ता इति सन्यस्य सर्वतन्त्रः परमेश्वर एव सर्वकर्ता नाहं कश्चित् इति निश्चित्य लोकानुग्रहं चिकीर्षुः लोकाचारं युद्धात्मकम् अनुतिष्ठ।'),
('abhinavagupta-sc:source:3.31','Abhinavagupta','gita.3.31','sa','commentary','।।3.31 3.32।।ये म इति। ये त्वेतदिति। एतच्च मतमाश्रित्य यः कश्चित् यत्किंचित् करोति तत्तस्य न बन्धकम्। एतस्मिंस्तु ज्ञाने ये न श्रद्धालवः ( श्रद्धालवाः) ते विनष्टाः अविरतं जन्ममरणादि ( S omitsआदि) भयभावितत्त्वात्।'),
('abhinavagupta-sc:source:3.32','Abhinavagupta','gita.3.32','sa','commentary','।।3.31 3.32।।ये म इति। ये त्वेतदिति। एतच्च मतमाश्रित्य यः कश्चित् यत्किंचित् करोति तत्तस्य न बन्धकम्। एतस्मिंस्तु ज्ञाने ये न श्रद्धालवः ( श्रद्धालवाः) ते विनष्टाः अविरतं जन्ममरणादि ( S omitsआदि) भयभावितत्त्वात्।'),
('abhinavagupta-sc:source:3.33','Abhinavagupta','gita.3.33','sa','commentary','।।3.33।।सदृशमिति। योऽपि च ज्ञानी न तस्य व्यवहारे भोजनादौ विपर्यासः कश्चित्। अपि तु सोऽपि सत्त्वाद्युचितमेव चेष्टते एवमेव जानन्। यतः ( N अतः) भूतानां पृथिव्यादीनां प्रकृतौ विलयः आत्मा च अकर्ता नित्यमुक्त इति कस्य जन्मादिनिग्रहः।'),
('abhinavagupta-sc:source:3.34','Abhinavagupta','gita.3.34','sa','commentary','।।3.34 3.35।।कथं तर्हि बन्धः इत्थमित्युच्यते (N omits इत्थम् K omits इति)।इन्द्रियस्येति। श्रेयानिति। संसारी च प्रतिविषयं रागं द्वेषं च गृह्णाति यतः कर्माणि आत्मकर्तृकाण्येव विमूढत्वादभिमन्यते इति सममपि भोजनादिव्यवहारं कुर्वतोः ज्ञानिसंसारिणोरस्त्ययं विशेषः। अयं नः सिद्धान्तः सर्वथा मुक्तसंगस्य स्वधर्मचारिणो नास्ति कश्चित् पुण्यपापात्मको बन्धः। स्वधर्मो हि हृदयादनपायी स्वरसनिरूढ ( N K निगूढः) एव न तेन कश्चिदपि रिक्तो जन्तुर्जायते इत्यत्याज्यः।'),
('abhinavagupta-sc:source:3.35','Abhinavagupta','gita.3.35','sa','commentary','।।3.34 3.35।।कथं तर्हि बन्धः इत्थमित्युच्यते (N omits इत्थम् K omits इति)।इन्द्रियस्येति। श्रेयानिति। संसारी च प्रतिविषयं रागं द्वेषं च गृह्णाति यतः कर्माणि आत्मकर्तृकाण्येव विमूढत्वादभिमन्यते इति सममपि भोजनादिव्यवहारं कुर्वतोः ज्ञानिसंसारिणोरस्त्ययं विशेषः। अयं नः सिद्धान्तः सर्वथा मुक्तसंगस्य स्वधर्मचारिणो नास्ति कश्चित् पुण्यपापात्मको बन्धः। स्वधर्मो हि हृदयादनपायी स्वरसनिरूढ ( N K निगूढः) एव न तेन कश्चिदपि रिक्तो जन्तुर्जायते इत्यत्याज्यः।'),
('abhinavagupta-sc:source:3.36','Abhinavagupta','gita.3.36','sa','commentary','।।3.36।।अथेति। पापं पापतया विदन्नपि जनः कथं तत्र प्रवर्तते इति प्रशनः। अस्य प्रश्नस्योत्थापने अयमाशयः। स्वधर्मो यदि स्वहृदयादनपायि (S हृदयानपायि ) त्वादत्याज्यः कथं तर्ह्यधर्माचरणमेषाम् (S omits तर्हि) इति कोऽयं स्वधर्मो नाम येनारिक्तो (S येन न रिक्तो N येनानतिरिक्तो) जन्तुः इत्युक्तं भवति।'),
('abhinavagupta-sc:source:3.37','Abhinavagupta','gita.3.37','sa','commentary','।।3.37।।अत्र उत्तरं सत्यपि धर्मे हृदिस्थे आगन्तुकावरणकृतोऽयं (N काचरणकृ ) विप्लवो न तु तदभवकृतः (N तदभावप्लुतः) इत्याशयेन।काम एष इति। द्वाभ्यामेतच्छब्दाभ्यामनयोरत्यन्तावैषम्यं (S अत्यन्तवैषम्यम्) सूच्यते। एतौ च कामक्रोधौ नित्यसंबन्धिनौ अन्योन्याविनाभावेन वर्तेते इत्येकरुपतयैव व्याचष्टे। एष च महस्य सुखस्य अशनः ग्रासकारकः महतः पापस्य हेतुत्त्वाच्च क्रोध एव पापदायी। एनं च वैरिणं प्राज्ञो जानीयात्।'),
('abhinavagupta-sc:source:3.38','Abhinavagupta','gita.3.38','sa','commentary','।।3.38।।धूमेनेति। दृष्टान्तत्रयेण दुरुपसर्गत्वम् (K दुरुपसर्पत्वम्) अकार्यकरत्वं जुगुप्सास्पदत्वं च उक्तम्। अयमिति आत्मा।'),
('abhinavagupta-sc:source:3.39','Abhinavagupta','gita.3.39','sa','commentary','।।3.39।।आवृतमिति। कामरूप इच्छायां यतश्चरति। अनलेन च अग्निनेव पूरयितुमशक्येन दृष्टादृष्टद्वयदाहकत्वात्।'),
('abhinavagupta-sc:source:3.40','Abhinavagupta','gita.3.40','sa','commentary','।।3.40।।इन्द्रियाणीति। आदाविन्द्रियेषु व्यापृतेषु सत्सु तिष्ठति। यथा चक्षुषा शत्रुः दृष्टः इन्द्रियप्रदेशेएव क्रोधमात्मनो जनयति। ततो मनसि संकल्पे ततो बुद्धौ निश्चये एतद्द्वारेण मोहं जनयन् ज्ञानंनाशयति।'),
('abhinavagupta-sc:source:3.41','Abhinavagupta','gita.3.41','sa','commentary','।।3.41।।अस्य निवारणोपायमाह तस्मादिति। तस्मादादौ इन्द्रियाणि नियमयेत्। क्रोधादिकं इन्द्रियेषु प्रथमं न गृह्णीयात्। ज्ञानं ब्रह्मज्ञानं विज्ञानं च भगवन्मयीं क्रियां नाशयति यतः ( N K हि यतः) अतः (S omits अतः) पाप्मानं (S पापम्) क्रोधं त्यज। अथवा ज्ञानेन मनसा विज्ञानेन बुद्ध्या च नाशनं वारणं कृत्वा इति क्रियाविशेषणम्। इन्द्रियेषु उत्पन्नं संकल्पेन गृह्णीयात् संकल्पितं वा न निश्चिनुयात् इति तात्पर्यम्।'),
('abhinavagupta-sc:source:3.42','Abhinavagupta','gita.3.42','sa','commentary','।।3.42 3.43।।अत्र युक्तिं श्लोकद्वयेनाह (S omits श्लोकद्वयेन) इन्द्रियाणीति। एवमिति। यत इन्द्रियाणि शत्रुलक्षणात् विषयात् अन्यानि तेभ्यश्चान्यत् मनः तस्मादपि बुद्धेर्व्यतिरेकः बुद्धेरपि यस्यान्यस्वभावत्वं स आत्मा। एवमिन्द्रियोत्पन्नेन क्रोधेन कथं मनसः बुद्धेरात्मनो वा क्षोभ इति पर्यालोचयेत् इत्यर्थः।रहस्यविदां त्वयमाशयः (N ह्ययमाशयः) बुद्धेः यः परत्र वर्तते परोऽहंकारः सर्वमहम् इत्यभेदात्मा स खलु परमोऽभेदः। अत एव च परिपूर्णस्य खण्डनाभावात् न क्रोधादय उत्पद्यन्ते (S N उदयन्ते)। अतः परमहंकारं परमोत्साहं संविदात्मकं (K परोत्साहसंवि ) गृहीत्वा क्रोधमविद्यत्मानं शत्रु जहि इति।।।शिवम्।।'),
('abhinavagupta-sc:source:3.43','Abhinavagupta','gita.3.43','sa','commentary','।।3.42 3.43।।अत्र युक्तिं श्लोकद्वयेनाह (S omits श्लोकद्वयेन) इन्द्रियाणीति। एवमिति। यत इन्द्रियाणि शत्रुलक्षणात् विषयात् अन्यानि तेभ्यश्चान्यत् मनः तस्मादपि बुद्धेर्व्यतिरेकः बुद्धेरपि यस्यान्यस्वभावत्वं स आत्मा। एवमिन्द्रियोत्पन्नेन क्रोधेन कथं मनसः बुद्धेरात्मनो वा क्षोभ इति पर्यालोचयेत् इत्यर्थः।रहस्यविदां त्वयमाशयः (N ह्ययमाशयः) बुद्धेः यः परत्र वर्तते परोऽहंकारः सर्वमहम् इत्यभेदात्मा स खलु परमोऽभेदः। अत एव च परिपूर्णस्य खण्डनाभावात् न क्रोधादय उत्पद्यन्ते (S N उदयन्ते)। अतः परमहंकारं परमोत्साहं संविदात्मकं (K परोत्साहसंवि ) गृहीत्वा क्रोधमविद्यत्मानं शत्रु जहि इति।।।शिवम्।।'),
('abhinavagupta-sc:source:4.1','Abhinavagupta','gita.4.1','sa','commentary','।।4.1 4.3।।एवमित्यादि उत्तमम् इत्यन्तम्। एतच्च गुरुपरम्पराप्राप्तमपि (S परम्परायातमपि K परम्परया प्राप्तमपि) अद्यत्वे नष्टमित्यनेन (S N अद्यत्वे तन्नष्ट) भगवान् अस्य ज्ञानस्य दुर्लभतां गौरवं च प्रदर्शयति। भक्तोऽसि मे सखा चेति। त्वं भक्तः मत्परमः सखा च। चशब्देन अन्वाचय उच्यते। तेन यथा भिक्षाटने भिक्षायां प्राधान्यं गवानयने त्वप्राधान्यम् एवं भक्तिरत्र गुरुं प्रति प्रधानं न सखित्वमपीति तात्पर्यार्थं।'),
('abhinavagupta-sc:source:4.2','Abhinavagupta','gita.4.2','sa','commentary','।।4.1 4.3।।एवमित्यादि उत्तमम् इत्यन्तम्। एतच्च गुरुपरम्पराप्राप्तमपि (S परम्परायातमपि K परम्परया प्राप्तमपि) अद्यत्वे नष्टमित्यनेन (S N अद्यत्वे तन्नष्ट) भगवान् अस्य ज्ञानस्य दुर्लभतां गौरवं च प्रदर्शयति। भक्तोऽसि मे सखा चेति। त्वं भक्तः मत्परमः सखा च। चशब्देन अन्वाचय उच्यते। तेन यथा भिक्षाटने भिक्षायां प्राधान्यं गवानयने त्वप्राधान्यम् एवं भक्तिरत्र गुरुं प्रति प्रधानं न सखित्वमपीति तात्पर्यार्थं।'),
('abhinavagupta-sc:source:4.3','Abhinavagupta','gita.4.3','sa','commentary','।।4.1 4.3।।एवमित्यादि उत्तमम् इत्यन्तम्। एतच्च गुरुपरम्पराप्राप्तमपि (S परम्परायातमपि K परम्परया प्राप्तमपि) अद्यत्वे नष्टमित्यनेन (S N अद्यत्वे तन्नष्ट) भगवान् अस्य ज्ञानस्य दुर्लभतां गौरवं च प्रदर्शयति। भक्तोऽसि मे सखा चेति। त्वं भक्तः मत्परमः सखा च। चशब्देन अन्वाचय उच्यते। तेन यथा भिक्षाटने भिक्षायां प्राधान्यं गवानयने त्वप्राधान्यम् एवं भक्तिरत्र गुरुं प्रति प्रधानं न सखित्वमपीति तात्पर्यार्थं।'),
('abhinavagupta-sc:source:4.4','Abhinavagupta','gita.4.4','sa','commentary','।।4.4।।अपरमिति। अर्जुनो भगवत्स्वरूपं जानन्नपि लोके स्फुटीकर्तुं पृच्छति।'),
('abhinavagupta-sc:source:4.5','Abhinavagupta','gita.4.5','sa','commentary','।।4.5 4.9।।बहूनि इत्यादि अर्जुन इत्यन्तम्। श्रीभगवान् किल पूर्णषाड्गुण्यत्वात् शरीरसंपर्कमात्ररहितोऽपि स्थितिकारित्वात् कारुणिकतया आत्मांशं सृजति। आत्मा पूर्णषाड्गुण्यः अंशः उपकारकत्वेन अप्रधानभूतो ( N omit अ) यत्र तत् आत्मांशं शरीरं गृह्णाति इत्यर्थः। अत एवास्य जन्म दिव्यम् यत आत्ममायया योगप्रज्ञया स्वस्वातन्त्रयशक्त्या ( omits स्व) आरब्धम् न कर्मभिः। कर्मापि दिव्यम् फलदानासमर्थत्वात्। यश्चैवमेतत्तत्त्वं वेत्ति आत्मन्यप्येवमेव मन्यते सोऽवश्यं भगवद्वासुदेवतत्त्वं जानाति।'),
('abhinavagupta-sc:source:4.6','Abhinavagupta','gita.4.6','sa','commentary','।।4.5 4.9।।बहूनि इत्यादि अर्जुन इत्यन्तम्। श्रीभगवान् किल पूर्णषाड्गुण्यत्वात् शरीरसंपर्कमात्ररहितोऽपि स्थितिकारित्वात् कारुणिकतया आत्मांशं सृजति। आत्मा पूर्णषाड्गुण्यः अंशः उपकारकत्वेन अप्रधानभूतो ( N omit अ) यत्र तत् आत्मांशं शरीरं गृह्णाति इत्यर्थः। अत एवास्य जन्म दिव्यम् यत आत्ममायया योगप्रज्ञया स्वस्वातन्त्रयशक्त्या ( omits स्व) आरब्धम् न कर्मभिः। कर्मापि दिव्यम् फलदानासमर्थत्वात्। यश्चैवमेतत्तत्त्वं वेत्ति आत्मन्यप्येवमेव मन्यते सोऽवश्यं भगवद्वासुदेवतत्त्वं जानाति।'),
('abhinavagupta-sc:source:4.7','Abhinavagupta','gita.4.7','sa','commentary','।।4.5 4.9।।बहूनि इत्यादि अर्जुन इत्यन्तम्। श्रीभगवान् किल पूर्णषाड्गुण्यत्वात् शरीरसंपर्कमात्ररहितोऽपि स्थितिकारित्वात् कारुणिकतया आत्मांशं सृजति। आत्मा पूर्णषाड्गुण्यः अंशः उपकारकत्वेन अप्रधानभूतो ( N omit अ) यत्र तत् आत्मांशं शरीरं गृह्णाति इत्यर्थः। अत एवास्य जन्म दिव्यम् यत आत्ममायया योगप्रज्ञया स्वस्वातन्त्रयशक्त्या ( omits स्व) आरब्धम् न कर्मभिः। कर्मापि दिव्यम् फलदानासमर्थत्वात्। यश्चैवमेतत्तत्त्वं वेत्ति आत्मन्यप्येवमेव मन्यते सोऽवश्यं भगवद्वासुदेवतत्त्वं जानाति।');
