INSERT INTO commentary_fts (unit_id,author,canonical_ref,language,content_type,content) VALUES
('abhinavagupta-sc:source:13.26','Abhinavagupta','gita.13.25','sa','commentary','।।13.25 -- 13.26।।ध्यानेनेति। अन्य इति। ईदृशं च ज्ञानं प्रधानम्। कैश्चित् [आत्मा] आत्मतया उपास्यते अन्यैः प्रागुक्तेन सांख्यनयेन अपरैः कर्मणा इतरैरपि स्वयमीदृशं (?N ईदृग्) ज्ञानमजानद्भिरपि श्रवणप्रवणैः यथाश्रुतमेवोपास्यते। तेऽपि मृत्युं संसारं तरन्ति। येन केनचिदुपायेन,भगवत्तत्त्वमुपास्यमानमुत्तारयति। अतः सर्वथा एवमासीतेत्युक्तम्।'),
('abhinavagupta-sc:source:13.27','Abhinavagupta','gita.13.26','sa','commentary','।।13.27।।यावदिति। यत्किंचित् चरम् अचरं च तत् सर्वं क्षेत्रज्ञातिरेकि न संभवतीति।'),
('abhinavagupta-sc:source:13.28','Abhinavagupta','gita.13.27','sa','commentary','।।13.28।।अत एव -- ।'),
('abhinavagupta-sc:source:13.29','Abhinavagupta','gita.13.28','sa','commentary','।।13.29।।सममिति। सर्वत्रैव समबुद्धिर्योगी आत्मानं न हिनस्ति दुस्तरे संसारार्णवे न पातयति (?N न हिनस्ति? न दुस्तरे संसारार्णवे पातयति)।'),
('abhinavagupta-sc:source:13.30','Abhinavagupta','gita.13.29','sa','commentary','।।13.30।।प्रकृत्येति। यस्य हि ईदृशी स्थिरतरा बुद्धिर्भवति प्रकृतिरेवेदं करोति? नाहं किञ्चित् इति (K omits इति) स सर्वं कुर्वाणोऽपि न करोति। एवमकर्तृत्वम्।'),
('abhinavagupta-sc:source:13.31','Abhinavagupta','gita.13.30','sa','commentary','।।13.31 -- 13.33।।यदि वा -- यदेत्यादि नोपलिप्यत इत्यन्तम्। विस्तीर्णत्वेन सर्वव्याप्त्या यदा भूतानां पृथक्तां भिन्नताम् (S चित्रताम्) आत्मन्येव पश्यति? आत्मन एव च उदितां तां मन्यते? तदापि सर्वकर्तृत्त्वात् न लेपभाक् यतः असौ परमात्मैव शरीरस्थोऽपि न लिप्यते आकाशवत्।'),
('abhinavagupta-sc:source:13.32','Abhinavagupta','gita.13.31','sa','commentary','।।13.31 -- 13.33।।यदि वा -- यदेत्यादि नोपलिप्यत इत्यन्तम्। विस्तीर्णत्वेन सर्वव्याप्त्या यदा भूतानां पृथक्तां भिन्नताम् (S चित्रताम्) आत्मन्येव पश्यति? आत्मन एव च उदितां तां मन्यते? तदापि सर्वकर्तृत्त्वात् न लेपभाक् यतः असौ परमात्मैव शरीरस्थोऽपि न लिप्यते आकाशवत्।'),
('abhinavagupta-sc:source:13.33','Abhinavagupta','gita.13.32','sa','commentary','।।13.31 -- 13.33।।यदि वा -- यदेत्यादि नोपलिप्यत इत्यन्तम्। विस्तीर्णत्वेन सर्वव्याप्त्या यदा भूतानां पृथक्तां भिन्नताम् (S चित्रताम्) आत्मन्येव पश्यति? आत्मन एव च उदितां तां मन्यते? तदापि सर्वकर्तृत्त्वात् न लेपभाक् यतः असौ परमात्मैव शरीरस्थोऽपि न लिप्यते आकाशवत्।'),
('abhinavagupta-sc:source:13.34','Abhinavagupta','gita.13.33','sa','commentary','।।13.34।।यथेति। ननु एकः परमात्मा कथमनेकानि क्षेत्राणि व्याप्नोति इत्याशङ्का प्रसिद्धेन रविणा दृष्टान्तेन अपाकृता। कृत्स्नं क्षेत्रम्? चराचराणि क्षेत्राणीत्यर्थः।'),
('abhinavagupta-sc:source:13.35','Abhinavagupta','gita.13.34','sa','commentary','।।13.35।।क्षेत्रेति। एवमध्यायेन यदुक्तं ज्ञेयं? ज्ञानं? क्षेत्रक्षेत्रज्ञयोरन्तरं? भूतप्रकृतेश्च (?N क्षेत्रक्षेत्रज्ञयोरन्तरं भूतप्रकृतेरन्तरं भूतप्रकृतेश्च) स्वल्पात् परिणामधर्मत्वात् मोचनम्? तत् ये ज्ञानलक्षणेन (S??N येन ज्ञानलक्षणेन) सर्वत्राप्रतिहतेन अलौकिकेन चक्षुषा पश्यन्ति ते वासुदेवतां प्राप्य लभन्त एव परमं (?N परं) शिवमिति।।।शिवम्।।'),
('abhinavagupta-sc:source:14.1','Abhinavagupta','gita.14.1','sa','commentary','।।14.1।।परमिति। यदेव पूर्वोक्तं ज्ञानं? तदेव पुनः प्रकर्षेण प्रत्येकं गुणस्वरूपनिरूपणाय वैतत्येन (S अवैतत्येन) वक्ष्यामि। यज्ज्ञात्वा इत्यनेन अस्य ज्ञानस्य दृष्टप्रत्ययतां प्रसिद्धिं चाह।'),
('abhinavagupta-sc:source:14.2','Abhinavagupta','gita.14.2','sa','commentary','।।14.2।।इदमिति। व्ययन्ति इति छान्दसत्वात् तिङ्प्रत्ययः। एवमन्यत्रापि सुप्तिङ्प्रत्यये वाच्यम्।'),
('abhinavagupta-sc:source:14.3','Abhinavagupta','gita.14.3','sa','commentary','।।14.3।।तत्रादौ संसृतौ क्रममाह। हातव्ये ज्ञाते तत्करणे च? सुकरं हि हानम् -- ममेति। मम तावत् अव्यपदेश्यपरमानन्दरूपस्य महद् ब्रह्म बृंहकात्मीयशक्तिरूपं ब्रह्म। आत्मीयामेव हि विमर्शशक्तिमालम्ब्य अहमनादीन् आत्माणून् अनुग्रहार्थ संसारयामि।'),
('abhinavagupta-sc:source:14.4','Abhinavagupta','gita.14.4','sa','commentary','।।14.4।।अत एव -- सर्वयोनिष्विति। सर्वासु योनिषु आदिकारणतया (S? आद्यकारणतया) बृंहिका भगवच्छक्तिः सकलसंसारजननस्वभावा (?K -- वमनस्वभावा) माता। पिता त्वहं शक्तिमान् अव्यपदेश्यः।'),
('abhinavagupta-sc:source:14.5','Abhinavagupta','gita.14.5','sa','commentary','।।14.5।।सत्त्वमिति। देही चायं आत्मतया सत्त्वरजस्तमोभिर्धर्मैः अपवर्गपर्यन्ताय भोगाय निबद्ध्यते।'),
('abhinavagupta-sc:source:14.6','Abhinavagupta','gita.14.6','sa','commentary','।।14.6 -- 14.8।।क्रमेणैषां रूपमुच्यते -- तत्रेत्यादि भारतेत्यन्तम्। सत्त्वं निर्मलम्। तृष्णासंगस्य समुद्भवो यतः। दुर्लभस्यापि चिरतरसंचितपुण्यशतलब्धस्य अपवर्गप्राप्तावेककारणस्य मानुष्यकस्य वृथा अतिवाहनं प्रमादः। तथाह्युक्तम्,(?N तथाभ्युक्तम्) -- आयुषः क्षण एकोऽपि सर्वरत्नैर्न लभ्यते।स वृथा नीयते येन स प्रमादी नराधमः।।14.इति (S in the margin? and ?N in the text itself add the followingयथा वा श्रीमद्भागवते -- निद्रया ह्रियते नक्तं व्यवायेन च वा वयः।दिवा चार्थेहया राजन् कुटुम्बभरणेन वा।।1।।देहापत्यकलत्रादिष्वात्मसैन्येष्वसत्स्वपि।तेषां प्रमत्तो निधनं पश्यन्नपि न पश्यति।।2।। -- The hagavata Purana ( Gorakhpur Ed.) II? i? verse 34तथा --,किं प्रमत्तस्य बहुभिः परोक्षैर्हायनैरिह।वरं मुहूर्त्तं विदितं घटेत श्रेयसे यतः।।3।। -- ibid? 12.अयमेव प्रमादः तत्रैवैकादशस्कन्धे आत्महत्याशब्दवाच्यो निर्णीतो भगवता,यथा -- नृदेहमाद्यं सुलभं सुदुर्लभं प्लवं सुकल्पं गुरुकर्णधारम्।मयानुकूलेन नभस्वतेरितं पुमान् भवाब्धिं न तरेत्स आत्महा।।4।। इति -- ibid. XI? xx? 17.)आलस्यं शुभकरणीयेषु। निःशेषेण द्राणं कुत्सिता गतिः निद्रा।'),
('abhinavagupta-sc:source:14.7','Abhinavagupta','gita.14.7','sa','commentary','।।14.6 -- 14.8।।क्रमेणैषां रूपमुच्यते -- तत्रेत्यादि भारतेत्यन्तम्। सत्त्वं निर्मलम्। तृष्णासंगस्य समुद्भवो यतः। दुर्लभस्यापि चिरतरसंचितपुण्यशतलब्धस्य अपवर्गप्राप्तावेककारणस्य मानुष्यकस्य वृथा अतिवाहनं प्रमादः। तथाह्युक्तम्,(?N तथाभ्युक्तम्) -- आयुषः क्षण एकोऽपि सर्वरत्नैर्न लभ्यते।स वृथा नीयते येन स प्रमादी नराधमः।।14.इति (S in the margin? and ?N in the text itself add the followingयथा वा श्रीमद्भागवते -- निद्रया ह्रियते नक्तं व्यवायेन च वा वयः।दिवा चार्थेहया राजन् कुटुम्बभरणेन वा।।1।।देहापत्यकलत्रादिष्वात्मसैन्येष्वसत्स्वपि।तेषां प्रमत्तो निधनं पश्यन्नपि न पश्यति।।2।। -- The hagavata Purana ( Gorakhpur Ed.) II? i? verse 34तथा --,किं प्रमत्तस्य बहुभिः परोक्षैर्हायनैरिह।वरं मुहूर्त्तं विदितं घटेत श्रेयसे यतः।।3।। -- ibid? 12.अयमेव प्रमादः तत्रैवैकादशस्कन्धे आत्महत्याशब्दवाच्यो निर्णीतो भगवता,यथा -- नृदेहमाद्यं सुलभं सुदुर्लभं प्लवं सुकल्पं गुरुकर्णधारम्।मयानुकूलेन नभस्वतेरितं पुमान् भवाब्धिं न तरेत्स आत्महा।।4।। इति -- ibid. XI? xx? 17.)आलस्यं शुभकरणीयेषु। निःशेषेण द्राणं कुत्सिता गतिः निद्रा।'),
